    let served = match &a.serving.tls {
        None => axum::serve(tcp, app).await,
        Some((cert, key)) => {
            let acceptor = tls::acceptor(cert, key)?;
            axum::serve(TlsListener { tcp, acceptor }, app).await
        }
    };
    served.map_err(|e| e.to_string())
