("""/// The stages that exist only to write and prove acceptance tests.""","""/// Every step in the order work flows through them, short and full
/// pipelines merged. A workflow may order its steps otherwise; this order
/// places a step a workflow left out (`next_listed`).
const ORDER: [Stage; 22] = [
    Stage::Prepare,
    Stage::Scope,
    Stage::Discover,
    Stage::Plan,
    Stage::Define,
    Stage::Specify,
    Stage::Baseline,
    Stage::Build,
    Stage::Implement,
    Stage::Checks,
    Stage::Verify,
    Stage::Refactor,
    Stage::Acceptance,
    Stage::CodeReview,
    Stage::Ship,
    Stage::Ci,
    Stage::Prove,
    Stage::Comprehend,
    Stage::Land,
    Stage::Merge,
    Stage::Deploy,
    Stage::Learn,
];

fn rank(stage: Stage) -> usize {
    ORDER.iter().position(|s| *s == stage).unwrap_or(ORDER.len())
}

/// The step after `at` in `stages`. A stage the list does not have, as a
/// fix loop's return to a step the workflow left out, goes on to the first
/// listed step that comes after it in `ORDER`.
pub fn next_listed(stages: &[Stage], at: Stage) -> Option<Stage> {
    match stages.iter().position(|s| *s == at) {
        Some(i) => stages.get(i + 1).copied(),
        None => stages.iter().copied().find(|s| rank(*s) > rank(at)),
    }
}

/// Whether `steps` make a workflow (D35): each a step a person can
/// oversee, none twice, and one that lands the change (land or merge),
/// with only deploy and learn after it.
pub fn check_workflow(steps: &[Stage]) -> Result<(), String> {
    for (i, s) in steps.iter().enumerate() {
        if !s.dialed() {
            return Err(format!("{s:?} is not a step"));
        }
        if steps[..i].contains(s) {
            return Err(format!("{s:?} is in the workflow twice"));
        }
    }
    let lands = steps
        .iter()
        .position(|s| matches!(s, Stage::Land | Stage::Merge))
        .ok_or("a workflow needs land or merge, or nothing lands")?;
    match steps[lands + 1..]
        .iter()
        .find(|s| !matches!(s, Stage::Deploy | Stage::Learn))
    {
        Some(s) => Err(format!("{s:?} comes after the change lands")),
        None => Ok(()),
    }
}

