//! Workflows (PLAN.md D35, W1): a named list of steps, each with its dial,
//! kept as versions. The built-in workflows are not kept here: their steps
//! are the pipelines', and their dials the settings'. They cannot be changed
//! or deleted, only copied. `Store` extends this trait.

use bastion_core::{Dial, Dials, Pipeline, Stage, check_workflow};
use serde_json::{Value, json};

use crate::store::{Answer, SqlStore, Store, name, parse};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Workflow {
    pub id: String,
    pub name: String,
    /// 0 for a built-in workflow.
    pub version: u64,
    pub steps: Vec<(Stage, Dial)>,
}

impl Workflow {
    pub fn stages(&self) -> Vec<Stage> {
        self.steps.iter().map(|(s, _)| *s).collect()
    }

    pub fn dials(&self) -> Dials {
        let mut d = Dials::default();
        for (stage, dial) in &self.steps {
            d.set(*stage, *dial);
        }
        d
    }

    pub fn built_in(&self) -> bool {
        self.version == 0
    }
}

pub trait WorkflowStore {
    /// The newest version of each kept workflow.
    fn workflows(&self) -> Answer<'_, Vec<Workflow>>;
    /// Keep `w` as its next version. Returns the version.
    fn save_workflow<'a>(&'a self, w: &'a Workflow, at: u64) -> Answer<'a, u64>;
    fn delete_workflow<'a>(&'a self, id: &'a str) -> Answer<'a, ()>;
}

/// The built-in workflows: id, name and pipeline.
const BUILT_IN: [(&str, &str, Pipeline); 3] = [
    ("short", "Short", Pipeline::Short),
    ("full", "Full", Pipeline::Full),
    (
        "full_no_acceptance",
        "Full, without acceptance tests",
        Pipeline::FullNoAcceptance,
    ),
];

/// The pipeline a built-in workflow runs, if `id` is one.
pub fn pipeline_of(id: &str) -> Option<Pipeline> {
    BUILT_IN.iter().find(|b| b.0 == id).map(|b| b.2)
}

/// Every workflow: the built-ins under the settings' `dials`, then the kept ones.
pub async fn all(store: &dyn Store, dials: &Dials) -> Result<Vec<Workflow>, String> {
    let built_in = BUILT_IN.iter().map(|(id, name, pipeline)| Workflow {
        id: id.to_string(),
        name: name.to_string(),
        version: 0,
        steps: pipeline.stages().into_iter().map(|s| (s, dials.at(s))).collect(),
    });
    Ok(built_in.chain(store.workflows().await?).collect())
}

pub async fn find(store: &dyn Store, dials: &Dials, id: &str) -> Result<Workflow, String> {
    all(store, dials)
        .await?
        .into_iter()
        .find(|w| w.id == id)
        .ok_or(format!("no workflow {id}"))
}

/// Keep `w` as a new version of a workflow that is not built in.
pub async fn save(store: &dyn Store, w: &Workflow, at: u64) -> Result<u64, String> {
    if pipeline_of(&w.id).is_some() {
        return Err(format!("{} is built in; copy it to change it", w.name));
    }
    if w.name.trim().is_empty() {
        return Err("a workflow needs a name".into());
    }
    check_workflow(&w.stages())?;
    store.save_workflow(w, at).await
}

pub const SCHEMA: [&str; 2] = [
    "CREATE TABLE IF NOT EXISTS workflows (
        id TEXT PRIMARY KEY CHECK (length(id) > 0),
        name TEXT NOT NULL CHECK (length(name) > 0),
        version INTEGER NOT NULL CHECK (version >= 1),
        updated_at INTEGER NOT NULL)",
    // Every version's steps, in order.
    "CREATE TABLE IF NOT EXISTS workflow_steps (
        workflow TEXT NOT NULL,
        version INTEGER NOT NULL CHECK (version >= 1),
        n INTEGER NOT NULL CHECK (n >= 0),
        stage TEXT NOT NULL CHECK (length(stage) > 0),
        dial TEXT NOT NULL CHECK (dial IN ('lights_on','dark')),
        PRIMARY KEY (workflow, version, n))",
];

fn step_of(r: &Value) -> Result<(String, Stage, Dial), String> {
    Ok((parse(r, "workflow")?, parse(r, "stage")?, parse(r, "dial")?))
}

impl WorkflowStore for SqlStore {
    fn workflows(&self) -> Answer<'_, Vec<Workflow>> {
        Box::pin(async move {
            let heads = self
                .rows(
                    "SELECT id, name, version FROM workflows ORDER BY name",
                    json!([]),
                    |r| Ok((parse(r, "id")?, parse(r, "name")?, parse(r, "version")?)),
                )
                .await?;
            let steps = self
                .rows(
                    "SELECT s.workflow, s.stage, s.dial FROM workflow_steps s
                     JOIN workflows w ON w.id = s.workflow AND w.version = s.version
                     ORDER BY s.workflow, s.n",
                    json!([]),
                    step_of,
                )
                .await?;
            Ok(heads
                .into_iter()
                .map(|(id, name, version): (String, String, u64)| Workflow {
                    steps: steps
                        .iter()
                        .filter(|s| s.0 == id)
                        .map(|s| (s.1, s.2))
                        .collect(),
                    id,
                    name,
                    version,
                })
                .collect())
        })
    }

    fn save_workflow<'a>(&'a self, w: &'a Workflow, at: u64) -> Answer<'a, u64> {
        Box::pin(async move {
            let kept = self.workflows().await?;
            let version = kept.iter().find(|k| k.id == w.id).map_or(0, |k| k.version) + 1;
            let head = json!({
                "sql": "INSERT INTO workflows (id, name, version, updated_at) VALUES (?, ?, ?, ?)
                        ON CONFLICT (id) DO UPDATE SET name = excluded.name, version = excluded.version, updated_at = excluded.updated_at",
                "params": [w.id, w.name.trim(), version, at],
            });
            let steps = w.steps.iter().enumerate().map(|(n, (stage, dial))| {
                json!({
                    "sql": "INSERT INTO workflow_steps (workflow, version, n, stage, dial) VALUES (?, ?, ?, ?, ?)",
                    "params": [w.id, version, n, name(stage), name(dial)],
                })
            });
            self.transaction(std::iter::once(head).chain(steps).collect())
                .await?;
            Ok(version)
        })
    }

    fn delete_workflow<'a>(&'a self, id: &'a str) -> Answer<'a, ()> {
        Box::pin(async move {
            let statements = ["workflow_steps WHERE workflow", "workflows WHERE id"]
                .map(|t| json!({ "sql": format!("DELETE FROM {t} = ?"), "params": [id] }));
            self.transaction(statements.to_vec()).await
        })
    }
}

