    let g = Graph {
        nodes: vec![
            node("tidy", Stage::Skill, "tidy-imports", &[], 0),
            node("lint", Stage::Command, "make lint", &["lint-report"], 100),
            node("land", Stage::Land, "", &[], 200),
        ],
        links: vec![Link {
