    let args = Issue {
        name: name.into(),
        label: "issued in Settings".into(),
    };
    let token = ipc::call::<String, String>(command::TOKEN_ISSUE, args)
        .await
        .map_err(ipc::Failure::text)?;
    Ok(format!("{name}'s new token, shown only now: {token}"))
}

