    let (symbol, color) = mark(&job.state);
    let dim = if down { "opacity-60" } else { "" };
    let unreachable = if down { " · unreachable" } else { "" };
    let (id, on) = (job.id.clone(), server.clone());
    view! {
        <li class={format!("border-t border-line first:border-t-0 {dim}")}>
