/// A model's id in the router's catalog: `<host>/<model>`, so two hosts
/// serving the same model never make the router's choice ambiguous.
pub fn catalog_id(host: &str, model: &str) -> String {
    format!("{host}/{model}")
}

/// The host's own name for a catalog model.
pub fn upstream_model<'a>(host: &str, model: &'a str) -> &'a str {
    model
