//! The data both N14 spikes draw, so their numbers compare: 200 jobs, a
//! 20-step workflow, a 2,000-line diff, and the theme's colors (D4).

pub const BG: &str = "#0f0d17";
pub const PANEL: &str = "#19162a";
pub const INK: &str = "#ece9f5";
pub const MUTED: &str = "#a39cb8";
pub const LINE: &str = "#2c2742";
pub const PRIMARY: &str = "#7c3aed";
pub const LINK: &str = "#c4b5fd";
pub const OK: &str = "#4ade80";
pub const BAD: &str = "#f87171";
pub const WARN: &str = "#fbbf24";

pub const PAGES: [&str; 10] = [
    "Jobs", "Workflows", "Constraints", "Capabilities", "Audit Log", "Evals", "Engine", "Settings", "Diff", "",
];

const STAGES: [&str; 5] = ["plan", "build", "checks", "review", "land"];
const STATES: [&str; 4] = ["running", "needs_you", "landed", "failed"];

#[derive(Clone)]
pub struct Job {
    pub id: String,
    pub request: String,
    pub stage: &'static str,
    pub state: &'static str,
}

pub fn jobs() -> Vec<Job> {
    (0..200)
        .map(|i| Job {
            id: format!("j{:08x}", 0x3b46_0000u32 + i * 7919),
            request: format!("Add a function number {i} to calc.py, with a test in test_calc.py."),
            stage: STAGES[i as usize % STAGES.len()],
            state: STATES[(i as usize / 3) % STATES.len()],
        })
        .collect()
}

/// The next state a pushed change gives a job.
pub fn next_state(state: &str) -> &'static str {
    let i = STATES.iter().position(|s| *s == state).unwrap_or(0);
    STATES[(i + 1) % STATES.len()]
}

pub struct Step {
    pub name: String,
    pub x: f64,
    pub y: f64,
}

pub const STEP_W: f64 = 168.0;
pub const STEP_H: f64 = 56.0;

/// 20 steps in four rows of five, each linked to the next and some to the
/// step two ahead.
pub fn workflow() -> (Vec<Step>, Vec<(usize, usize)>) {
    let steps = (0..20)
        .map(|i| Step {
            name: format!("step {i} · lights-on"),
            x: 24.0 + (i % 5) as f64 * 210.0,
            y: 24.0 + (i / 5) as f64 * 120.0,
        })
        .collect();
    let mut links: Vec<(usize, usize)> = (0..19).map(|i| (i, i + 1)).collect();
    links.extend((0..18).step_by(3).map(|i| (i, i + 2)));
    (steps, links)
}

/// One line of a diff and its mark: '+', '-' or ' '.
pub fn diff() -> Vec<(char, String)> {
    (0..2000)
        .map(|i| {
            let mark = match i % 7 {
                0 | 1 => '+',
                2 => '-',
                _ => ' ',
            };
            (mark, format!("{i:5}  def function_{i}(a, b):  return a * {i} + b  # line {i}"))
        })
        .collect()
}

pub fn now_ms() -> u128 {
    let since = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH);
    since.map_or(0, |d| d.as_millis())
}

/// Median, 95th percentile and worst of `samples`, in milliseconds.
pub fn summary(name: &str, mut samples: Vec<f64>) -> String {
    samples.sort_by(f64::total_cmp);
    let at = |q: f64| samples[((samples.len() - 1) as f64 * q) as usize];
    format!(
        "RESULT {name} n={} median={:.2} p95={:.2} max={:.2}",
        samples.len(),
        at(0.5),
        at(0.95),
        at(1.0)
    )
}

//! Spike N14 on GTK 4. `N14_MODE=jobs|canvas|diff` picks the screen; each
//! measures itself, prints `RESULT` lines and quits. `N14_STAY=1` keeps the
//! window open for a screenshot.

#[path = "../../n14-data.rs"]
mod data;

use std::cell::RefCell;
use std::rc::Rc;
use std::time::{Duration, Instant};

use gtk::prelude::*;
use gtk::{cairo, gdk, glib};

const FRAMES: usize = 300;
const PUSHES: usize = 30;

#[derive(Default)]
struct Probe {
    painted: bool,
    last_paint: Option<Instant>,
    intervals: Vec<f64>,
    pushed: Option<Instant>,
    repaints: Vec<f64>,
    done: bool,
}

fn css() -> String {
    use data::*;
    format!(
        "window, .page {{ background: {BG}; color: {INK}; font-family: system-ui, sans-serif; font-size: 14px; }}
         .sidebar {{ background: {BG}; border-right: 1px solid {LINE}; padding: 16px 12px; }}
         .brand {{ font-size: 18px; font-weight: 700; margin-bottom: 12px; }}
         .nav {{ padding: 8px 12px; border-radius: 8px; color: {INK}; }}
         .nav.active {{ background: {PRIMARY}; }}
         .panel {{ background: {PANEL}; border: 1px solid {LINE}; border-radius: 12px; padding: 12px 16px; }}
         .muted {{ color: {MUTED}; }}
         .id {{ color: {LINK}; font-family: monospace; }}
         .needs_you {{ color: {WARN}; }} .landed {{ color: {OK}; }} .failed {{ color: {BAD}; }} .running {{ color: {LINK}; }}
         h1 {{ font-size: 24px; font-weight: 700; }}
         textview, textview text {{ background: {PANEL}; color: {INK}; font-family: monospace; }}"
    )
}

fn label(text: &str, class: &str) -> gtk::Label {
    let l = gtk::Label::new(Some(text));
    l.set_xalign(0.0);
    if !class.is_empty() {
        l.add_css_class(class);
    }
    l
}

fn sidebar(active: &str) -> gtk::Box {
    let side = gtk::Box::new(gtk::Orientation::Vertical, 2);
    side.add_css_class("sidebar");
    side.set_size_request(200, -1);
    side.append(&label("Bastion", "brand"));
    for page in data::PAGES.iter().filter(|p| !p.is_empty()) {
        let item = label(page, "nav");
        if *page == active {
            item.add_css_class("active");
        }
        side.append(&item);
    }
    side
}

/// The Jobs page: 200 rows; returns the state labels a push changes.
fn jobs_page() -> (gtk::Widget, Vec<gtk::Label>) {
    let list = gtk::Box::new(gtk::Orientation::Vertical, 8);
    let mut states = Vec::new();
    for job in data::jobs() {
        let row = gtk::Box::new(gtk::Orientation::Horizontal, 12);
        row.add_css_class("panel");
        row.append(&label(&job.id, "id"));
        let request = label(&job.request, "");
        request.set_hexpand(true);
        request.set_ellipsize(gtk::pango::EllipsizeMode::End);
        row.append(&request);
        row.append(&label(job.stage, "muted"));
        let state = label(job.state, job.state);
        state.set_width_chars(10);
        row.append(&state);
        list.append(&row);
        states.push(state);
    }
    (page("Jobs", &list), states)
}

fn page(title: &str, body: &impl IsA<gtk::Widget>) -> gtk::Widget {
    let column = gtk::Box::new(gtk::Orientation::Vertical, 12);
    column.add_css_class("page");
    column.set_margin_start(24);
    column.set_margin_end(24);
    column.set_margin_top(16);
    column.append(&label(title, "h1"));
    column.last_child().unwrap().add_css_class("h1");
    column.append(body);
    let scroll = gtk::ScrolledWindow::new();
    scroll.set_child(Some(&column));
    scroll.set_hexpand(true);
    scroll.upcast()
}

fn rgb(cr: &cairo::Context, hex: &str) {
    let v = |i: usize| u8::from_str_radix(&hex[i..i + 2], 16).unwrap() as f64 / 255.0;
    cr.set_source_rgb(v(1), v(3), v(5));
}

/// The Workflows canvas: steps as rounded boxes, links as curves.
fn canvas_page(offset: Rc<RefCell<f64>>) -> (gtk::Widget, gtk::DrawingArea) {
    let area = gtk::DrawingArea::new();
    area.set_content_width(1100);
    area.set_content_height(520);
    let (steps, links) = data::workflow();
    area.set_draw_func(move |_, cr, _, _| {
        let at = |i: usize| {
            let s = &steps[i];
            (s.x + if i == 0 { *offset.borrow() } else { 0.0 }, s.y)
        };
        cr.set_line_width(2.0);
        rgb(cr, data::LINK);
        for &(a, b) in &links {
            let ((ax, ay), (bx, by)) = (at(a), at(b));
            let (x1, y1, x2, y2) = (ax + data::STEP_W, ay + data::STEP_H / 2.0, bx, by + data::STEP_H / 2.0);
            cr.move_to(x1, y1);
            cr.curve_to(x1 + 40.0, y1, x2 - 40.0, y2, x2, y2);
            cr.stroke().unwrap();
        }
        for (i, s) in steps.iter().enumerate() {
            let (x, y) = at(i);
            cr.new_sub_path();
            let (w, h, r) = (data::STEP_W, data::STEP_H, 10.0);
            cr.arc(x + w - r, y + r, r, -1.57, 0.0);
            cr.arc(x + w - r, y + h - r, r, 0.0, 1.57);
            cr.arc(x + r, y + h - r, r, 1.57, 3.14);
            cr.arc(x + r, y + r, r, 3.14, 4.71);
            cr.close_path();
            rgb(cr, data::PANEL);
            cr.fill_preserve().unwrap();
            rgb(cr, if i == 0 { data::PRIMARY } else { data::LINE });
            cr.stroke().unwrap();
            rgb(cr, data::INK);
            cr.move_to(x + 12.0, y + 32.0);
            cr.set_font_size(13.0);
            cr.show_text(&s.name).unwrap();
        }
    });
    (page("Workflows", &area), area)
}

/// A 2,000-line diff in one text view, added and removed lines colored.
fn diff_page() -> (gtk::Widget, gtk::Adjustment) {
    let buffer = gtk::TextBuffer::new(None);
    let add = buffer.create_tag(Some("add"), &[("foreground", &data::OK)]).unwrap();
    let del = buffer.create_tag(Some("del"), &[("foreground", &data::BAD)]).unwrap();
    for (mark, line) in data::diff() {
        let mut end = buffer.end_iter();
        let text = format!("{mark} {line}\n");
        match mark {
            '+' => buffer.insert_with_tags(&mut end, &text, &[&add]),
            '-' => buffer.insert_with_tags(&mut end, &text, &[&del]),
            _ => buffer.insert(&mut end, &text),
        }
    }
    let view = gtk::TextView::with_buffer(&buffer);
    view.set_editable(false);
    view.set_monospace(true);
    let scroll = gtk::ScrolledWindow::new();
    scroll.set_child(Some(&view));
    scroll.set_vexpand(true);
    scroll.set_hexpand(true);
    let adj = scroll.vadjustment();
    let column = gtk::Box::new(gtk::Orientation::Vertical, 12);
    column.add_css_class("page");
    column.append(&label("calc.py", "h1"));
    column.append(&scroll);
    (column.upcast(), adj)
}

fn finish(app: &gtk::Application, probe: &Rc<RefCell<Probe>>) {
    let mut p = probe.borrow_mut();
    if p.done {
        return;
    }
    p.done = true;
    if !p.intervals.is_empty() {
        println!("{}", data::summary("frame_ms", p.intervals.clone()));
    }
    if !p.repaints.is_empty() {
        println!("{}", data::summary("push_to_paint_ms", p.repaints.clone()));
    }
    if std::env::var("N14_STAY").is_err() {
        app.quit();
    }
}

fn activate(app: &gtk::Application, mode: &str) {
    let provider = gtk::CssProvider::new();
    provider.load_from_string(&css());
    gtk::style_context_add_provider_for_display(
        &gdk::Display::default().unwrap(),
        &provider,
        gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
    );
    let window = gtk::ApplicationWindow::new(app);
    window.set_default_size(1280, 900);
    window.set_title(Some("Bastion"));
    let root = gtk::Box::new(gtk::Orientation::Horizontal, 0);
    let probe = Rc::new(RefCell::new(Probe::default()));
    let offset = Rc::new(RefCell::new(0.0));
    let (body, animate): (gtk::Widget, Box<dyn Fn(usize)>) = match mode {
        "canvas" => {
            let (w, area) = canvas_page(offset.clone());
            let o = offset.clone();
            (w, Box::new(move |f| {
                *o.borrow_mut() = 300.0 * (f as f64 / 30.0).sin().abs();
                area.queue_draw();
            }))
        }
        "diff" => {
            let (w, adj) = diff_page();
            (w, Box::new(move |_| {
                let next = adj.value() + 40.0;
                adj.set_value(if next > adj.upper() - adj.page_size() { 0.0 } else { next });
            }))
        }
        _ => {
            let (w, states) = jobs_page();
            let (p, a) = (probe.clone(), app.clone());
            let count = Rc::new(RefCell::new(0usize));
            glib::timeout_add_local(Duration::from_millis(200), move || {
                if !p.borrow().painted {
                    return glib::ControlFlow::Continue;
                }
                let mut n = count.borrow_mut();
                if *n == PUSHES {
                    finish(&a, &p);
                    return glib::ControlFlow::Break;
                }
                let l = &states[(*n * 37) % states.len()];
                let next = data::next_state(&l.text());
                l.set_text(next);
                l.set_css_classes(&[next]);
                p.borrow_mut().pushed = Some(Instant::now());
                *n += 1;
                glib::ControlFlow::Continue
            });
            (w, Box::new(|_| {}))
        }
    };
    root.append(&sidebar(match mode {
        "canvas" => "Workflows",
        "diff" => "Diff",
        _ => "Jobs",
    }));
    root.append(&body);
    window.set_child(Some(&root));
    let animated = mode != "jobs";
    let frame = Rc::new(RefCell::new(0usize));
    let (p, a) = (probe.clone(), app.clone());
    window.add_tick_callback(move |_, _| {
        if animated && p.borrow().painted && !p.borrow().done {
            let mut f = frame.borrow_mut();
            *f += 1;
            animate(*f);
            if *f > FRAMES {
                finish(&a, &p);
            }
        }
        glib::ControlFlow::Continue
    });
    let p = probe.clone();
    window.connect_realize(move |w| {
        let p = p.clone();
        w.frame_clock().unwrap().connect_after_paint(move |_| {
            let mut p = p.borrow_mut();
            let now = Instant::now();
            if !p.painted {
                p.painted = true;
                println!("FIRST_PAINT {}", data::now_ms());
            }
            if let Some(t) = p.pushed.take() {
                p.repaints.push((now - t).as_secs_f64() * 1000.0);
            }
            if animated && !p.done {
                if let Some(last) = p.last_paint {
                    p.intervals.push((now - last).as_secs_f64() * 1000.0);
                }
            }
            p.last_paint = Some(now);
        });
    });
    window.present();
}

fn main() -> glib::ExitCode {
    let mode = std::env::var("N14_MODE").unwrap_or_else(|_| "jobs".into());
    let app = gtk::Application::builder().application_id("dev.tacoda.n14gtk").build();
    app.connect_activate(move |app| activate(app, &mode));
    app.run_with_args::<&str>(&[])
}

//! Spike N14 on iced. `N14_MODE=jobs|canvas|diff` picks the screen; each
//! measures itself, prints `RESULT` lines and quits. `N14_STAY=1` keeps the
//! window open for a screenshot.

#[path = "../../n14-data.rs"]
mod data;

use std::time::{Duration, Instant};

use iced::widget::canvas::{self, Canvas, Frame, Geometry, Path, Stroke};
use iced::widget::{column, container, row, scrollable, text, Column};
use iced::{mouse, window, Background, Border, Color, Element, Fill, Point, Rectangle, Renderer, Size, Subscription, Task, Theme};

const FRAMES: usize = 300;
const PUSHES: usize = 30;

fn hex(h: &str) -> Color {
    let v = |i: usize| u8::from_str_radix(&h[i..i + 2], 16).unwrap();
    Color::from_rgb8(v(1), v(3), v(5))
}

fn state_color(state: &str) -> Color {
    hex(match state {
        "needs_you" => data::WARN,
        "landed" => data::OK,
        "failed" => data::BAD,
        _ => data::LINK,
    })
}

#[derive(Debug, Clone)]
enum Message {
    Frame(Instant),
    Push,
}

struct App {
    mode: String,
    jobs: Vec<data::Job>,
    steps: Vec<data::Step>,
    links: Vec<(usize, usize)>,
    diff: Vec<(char, String)>,
    offset: f32,
    frame: usize,
    painted: bool,
    last: Option<Instant>,
    intervals: Vec<f64>,
    pushed: Option<Instant>,
    repaints: Vec<f64>,
    pushes: usize,
    done: bool,
}

impl App {
    fn new() -> (Self, Task<Message>) {
        let (steps, links) = data::workflow();
        let app = Self {
            mode: std::env::var("N14_MODE").unwrap_or_else(|_| "jobs".into()),
            jobs: data::jobs(),
            steps,
            links,
            diff: data::diff(),
            offset: 0.0,
            frame: 0,
            painted: false,
            last: None,
            intervals: vec![],
            pushed: None,
            repaints: vec![],
            pushes: 0,
            done: false,
        };
        (app, Task::none())
    }

    fn finish(&mut self) -> Task<Message> {
        if self.done {
            return Task::none();
        }
        self.done = true;
        if !self.intervals.is_empty() {
            println!("{}", data::summary("frame_ms", self.intervals.clone()));
        }
        if !self.repaints.is_empty() {
            println!("{}", data::summary("push_to_paint_ms", self.repaints.clone()));
        }
        if std::env::var("N14_STAY").is_ok() { Task::none() } else { iced::exit() }
    }

    fn update(&mut self, message: Message) -> Task<Message> {
        match message {
            Message::Frame(now) => {
                if !self.painted {
                    self.painted = true;
                    println!("FIRST_PAINT {}", data::now_ms());
                }
                if let Some(t) = self.pushed.take() {
                    self.repaints.push((now - t).as_secs_f64() * 1000.0);
                }
                if self.mode != "jobs" && !self.done {
                    if let Some(last) = self.last {
                        self.intervals.push((now - last).as_secs_f64() * 1000.0);
                    }
                    self.frame += 1;
                    self.offset = 300.0 * (self.frame as f32 / 30.0).sin().abs();
                    if self.frame > FRAMES {
                        self.last = Some(now);
                        return self.finish();
                    }
                }
                self.last = Some(now);
                if self.mode == "diff" {
                    let y = (self.frame as f32 * 40.0) % 40_000.0;
                    return iced::widget::operation::scroll_to(
                        "diff",
                        scrollable::AbsoluteOffset { x: 0.0, y },
                    );
                }
                Task::none()
            }
            Message::Push => {
                if !self.painted {
                    return Task::none();
                }
                if self.pushes == PUSHES {
                    return self.finish();
                }
                let job = &mut self.jobs[(self.pushes * 37) % 200];
                job.state = data::next_state(job.state);
                self.pushed = Some(Instant::now());
                self.pushes += 1;
                Task::none()
            }
        }
    }

    fn subscription(&self) -> Subscription<Message> {
        let frames = window::frames().map(Message::Frame);
        if self.mode == "jobs" {
            let pushes = iced::time::every(Duration::from_millis(200)).map(|_| Message::Push);
            Subscription::batch([frames, pushes])
        } else {
            frames
        }
    }

    fn view(&self) -> Element<'_, Message> {
        let (title, body): (&str, Element<'_, Message>) = match self.mode.as_str() {
            "canvas" => ("Workflows", Canvas::new(self).width(1100).height(520).into()),
            "diff" => ("calc.py", self.diff_view()),
            _ => ("Jobs", self.jobs_view()),
        };
        let page = column![text(title).size(24).color(hex(data::INK)), body]
            .spacing(12)
            .padding([16, 24]);
        let root = row![sidebar(if self.mode == "canvas" { "Workflows" } else if self.mode == "diff" { "Diff" } else { "Jobs" }), page];
        container(root)
            .width(Fill)
            .height(Fill)
            .style(|_| container::Style {
                background: Some(Background::Color(hex(data::BG))),
                text_color: Some(hex(data::INK)),
                ..Default::default()
            })
            .into()
    }

    fn jobs_view(&self) -> Element<'_, Message> {
        let rows = self.jobs.iter().map(|j| {
            container(
                row![
                    text(&j.id).font(iced::Font::MONOSPACE).color(hex(data::LINK)),
                    text(&j.request).width(Fill),
                    text(j.stage).color(hex(data::MUTED)),
                    text(j.state).color(state_color(j.state)).width(90),
                ]
                .spacing(12),
            )
            .padding([12, 16])
            .width(Fill)
            .style(panel)
            .into()
        });
        scrollable(Column::with_children(rows).spacing(8)).height(Fill).into()
    }

    fn diff_view(&self) -> Element<'_, Message> {
        let lines = self.diff.iter().map(|(mark, line)| {
            let color = match mark {
                '+' => hex(data::OK),
                '-' => hex(data::BAD),
                _ => hex(data::INK),
            };
            text(format!("{mark} {line}")).font(iced::Font::MONOSPACE).size(13).color(color).into()
        });
        let body = container(Column::with_children(lines)).padding(8).width(Fill).style(panel);
        scrollable(body).id("diff").height(Fill).into()
    }
}

fn panel(_: &Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(hex(data::PANEL))),
        border: Border { radius: 12.0.into(), width: 1.0, color: hex(data::LINE) },
        ..Default::default()
    }
}

fn sidebar(active: &str) -> Element<'static, Message> {
    let mut items = vec![text("Bastion").size(18).into()];
    for page in data::PAGES.iter().filter(|p| !p.is_empty()) {
        let on = *page == active;
        items.push(
            container(text(*page))
                .padding([8, 12])
                .width(Fill)
                .style(move |_| container::Style {
                    background: on.then(|| Background::Color(hex(data::PRIMARY))),
                    border: Border { radius: 8.0.into(), ..Default::default() },
                    ..Default::default()
                })
                .into(),
        );
    }
    container(Column::with_children(items).spacing(2))
        .width(200)
        .height(Fill)
        .padding([16, 12])
        .style(|_| container::Style {
            border: Border { width: 1.0, color: hex(data::LINE), ..Default::default() },
            ..Default::default()
        })
        .into()
}

impl canvas::Program<Message> for App {
    type State = ();

    fn draw(&self, _: &(), renderer: &Renderer, _: &Theme, bounds: Rectangle, _: mouse::Cursor) -> Vec<Geometry> {
        let mut frame = Frame::new(renderer, bounds.size());
        let at = |i: usize| {
            let s = &self.steps[i];
            Point::new(s.x as f32 + if i == 0 { self.offset } else { 0.0 }, s.y as f32)
        };
        let (w, h) = (data::STEP_W as f32, data::STEP_H as f32);
        for &(a, b) in &self.links {
            let (pa, pb) = (at(a), at(b));
            let (from, to) = (Point::new(pa.x + w, pa.y + h / 2.0), Point::new(pb.x, pb.y + h / 2.0));
            let curve = Path::new(|p| {
                p.move_to(from);
                p.bezier_curve_to(Point::new(from.x + 40.0, from.y), Point::new(to.x - 40.0, to.y), to);
            });
            frame.stroke(&curve, Stroke::default().with_width(2.0).with_color(hex(data::LINK)));
        }
        for (i, s) in self.steps.iter().enumerate() {
            let p = at(i);
            let rect = Path::rounded_rectangle(p, Size::new(w, h), 10.0.into());
            frame.fill(&rect, hex(data::PANEL));
            let edge = if i == 0 { data::PRIMARY } else { data::LINE };
            frame.stroke(&rect, Stroke::default().with_width(2.0).with_color(hex(edge)));
            frame.fill_text(canvas::Text {
                content: s.name.clone(),
                position: Point::new(p.x + 12.0, p.y + 20.0),
                color: hex(data::INK),
                size: 13.0.into(),
                ..canvas::Text::default()
            });
        }
        vec![frame.into_geometry()]
    }
}

fn main() -> iced::Result {
    iced::application(App::new, App::update, App::view)
        .subscription(App::subscription)
        .title("Bastion")
        .window_size(Size::new(1280.0, 900.0))
        .run()
}

