type Animate = Box<dyn Fn(usize)>;

fn canvas_screen() -> (gtk::Widget, Animate) {
    let offset = Rc::new(RefCell::new(0.0));
    let (w, area) = canvas_page(offset.clone());
    let animate = move |f: usize| {
        *offset.borrow_mut() = 300.0 * (f as f64 / 30.0).sin().abs();
        area.queue_draw();
    };
    (w, Box::new(animate))
}

fn diff_screen() -> (gtk::Widget, Animate) {
    let (w, adj) = diff_page();
    let animate = move |_| {
        let next = adj.value() + 40.0;
        let end = adj.upper() - adj.page_size();
        adj.set_value(if next > end { 0.0 } else { next });
    };
    (w, Box::new(animate))
}

/// Push one job's next state; stop after `PUSHES`.
fn push(states: &[gtk::Label], n: usize, probe: &Shared) {
    let l = &states[(n * 37) % states.len()];
    let next = data::next_state(&l.text());
    l.set_text(next);
    l.set_css_classes(&[next]);
    probe.borrow_mut().pushed = Some(Instant::now());
}

fn jobs_screen(app: &gtk::Application, probe: &Shared) -> (gtk::Widget, Animate) {
    let (w, states) = jobs_page();
    let (p, a) = (probe.clone(), app.clone());
    let mut n = 0;
    glib::timeout_add_local(Duration::from_millis(200), move || {
        if !p.borrow().painted {
            return glib::ControlFlow::Continue;
        }
        if n == PUSHES {
            finish(&a, &p);
            return glib::ControlFlow::Break;
        }
        push(&states, n, &p);
        n += 1;
        glib::ControlFlow::Continue
    });
    (w, Box::new(|_| {}))
}

/// Each frame moves the screen one step until `FRAMES`.
fn drive(window: &gtk::ApplicationWindow, app: &gtk::Application, probe: &Shared, animate: Animate) {
    let (p, a) = (probe.clone(), app.clone());
    let mut frame = 0;
    window.add_tick_callback(move |_, _| {
        if p.borrow().running() {
            frame += 1;
            animate(frame);
            if frame > FRAMES {
                finish(&a, &p);
            }
        }
        glib::ControlFlow::Continue
    });
}

fn watch_paints(window: &gtk::ApplicationWindow, probe: &Shared, animated: bool) {
    let p = probe.clone();
    window.connect_realize(move |w| {
        let p = p.clone();
        let clock = w.frame_clock().unwrap();
        clock.connect_after_paint(move |_| p.borrow_mut().on_paint(animated));
    });
}

fn activate(app: &gtk::Application, mode: Mode) {
    install_css();
    let window = gtk::ApplicationWindow::new(app);
    window.set_default_size(1280, 900);
    window.set_title(Some("Bastion"));
    let probe = Shared::default();
    let (body, animate) = match mode {
        Mode::Canvas => canvas_screen(),
        Mode::Diff => diff_screen(),
        Mode::Jobs => jobs_screen(app, &probe),
    };
    let root = gtk::Box::new(gtk::Orientation::Horizontal, 0);
    root.append(&sidebar(mode.page()));
    root.append(&body);
    window.set_child(Some(&root));
    let animated = mode != Mode::Jobs;
    if animated {
        drive(&window, app, &probe, animate);
    }
    watch_paints(&window, &probe, animated);
    window.present();
}

fn main() -> glib::ExitCode {
    let mode = Mode::from_env();
    let app = gtk::Application::builder().application_id("dev.tacoda.n14gtk").build();
    app.connect_activate(move |app| activate(app, mode));
    app.run_with_args::<&str>(&[])
}
