//! Bastion's window (PLAN.md D27, D28). It starts or attaches to the local
//! Bastion server and tells the page about every server it knows; the page
//! does the rest over HTTP.

mod commands;
mod local;
mod profile;
mod servers;

use bastion_protocol::event;
use profile::Profiles;
use servers::{Keychain, Servers};
use tauri::{AppHandle, Emitter, Manager, RunEvent, WindowEvent};

/// The checkout this build came from, which holds `worker-compose.yaml`.
// ponytail: a build-time path; packaging the stack replaces it (PLAN.md A11).
const CHECKOUT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/..");

/// Start or attach to the `local` Bastion server, with the checkout and
/// engine `profiles.toml` names, and load the servers the owner added.
fn setup(app: &mut tauri::App) -> Result<(), Box<dyn std::error::Error>> {
    let path = app.path().app_config_dir()?.join(profile::FILE_NAME);
    let checkout = std::path::Path::new(CHECKOUT).canonicalize()?;
    let profiles = Profiles::load_or_create(&path, checkout)?;
    let data = app.path().app_data_dir()?.join("server");
    let local = local::start(profiles.active(), &data)?;
    let file = app.path().app_config_dir()?.join(servers::FILE_NAME);
    app.manage(Servers::new(file, local, Box::new(Keychain)));
    Ok(())
}

/// The page decides a quit: it asks only while the stack runs.
fn ask_page(app: &AppHandle) {
    let _ = app.emit(event::QUIT_REQUESTED, ());
}

fn on_window(window: &tauri::Window, e: &WindowEvent) {
    if let WindowEvent::CloseRequested { api, .. } = e {
        api.prevent_close();
        ask_page(window.app_handle());
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .setup(setup)
        .on_window_event(on_window)
        .invoke_handler(tauri::generate_handler![
            commands::app::servers,
            commands::app::server_add,
            commands::app::server_remove,
            commands::app::quit,
        ])
        .build(tauri::generate_context!())
        .expect("error while building tauri application")
        .run(|app, e| {
            // ⌘Q has no exit code; the `quit` command exits with one.
            if let RunEvent::ExitRequested {
                api, code: None, ..
            } = e
            {
                api.prevent_exit();
                ask_page(app);
            }
        });
}
//! The `local` Bastion server (D30): a `bastion-server` on this machine, started by the
//! app, or the one already running. It outlives the app, so jobs go on.

use std::fs::File;
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use bastion_protocol::{LOCAL, Server};

use crate::profile::Profile;

/// The port the local server listens on.
pub const PORT: u16 = 49190;
/// How long a start may take before the app gives up on it.
const START_WAIT: Duration = Duration::from_secs(20);

/// The server binary this build runs.
// ponytail: the dev build's path; A13 ships it as a Tauri sidecar.
const BINARY: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../target/debug/bastion-server"
);

/// Attach to the local server, starting it first if nothing listens on its
/// port. `data` holds its token and its log.
pub fn start(profile: &Profile, data: &Path) -> Result<Server, String> {
    if !listening() {
        spawn(profile, data)?;
    }
    let token = data.join("token");
    let since = Instant::now();
    while !(listening() && token.exists()) {
        if since.elapsed() > START_WAIT {
            return Err(format!(
                "bastion-server did not start within {}s; see {}",
                START_WAIT.as_secs(),
                data.join("server.log").display()
            ));
        }
        std::thread::sleep(Duration::from_millis(200));
    }
    Ok(Server {
        name: LOCAL.into(),
        url: format!("http://127.0.0.1:{PORT}"),
        token: std::fs::read_to_string(&token)
            .map_err(|e| format!("{}: {e}", token.display()))?
            .trim()
            .into(),
    })
}

fn listening() -> bool {
    TcpStream::connect(("127.0.0.1", PORT)).is_ok()
}

/// Start the server in its own process group, so quitting the app leaves it running.
fn spawn(profile: &Profile, data: &Path) -> Result<(), String> {
    std::fs::create_dir_all(data).map_err(|e| format!("{}: {e}", data.display()))?;
    let log = File::create(data.join("server.log")).map_err(|e| e.to_string())?;
    let mut command = Command::new(PathBuf::from(BINARY));
    command
        .args(["--checkout", &profile.checkout.display().to_string()])
        .args(["--data", &data.display().to_string()])
        .args(["--port", &PORT.to_string()])
        .args(["--engine", &profile.engine_url])
        .current_dir(&profile.checkout)
        .stdin(Stdio::null())
        .stdout(log.try_clone().map_err(|e| e.to_string())?)
        .stderr(log);
    #[cfg(unix)]
    std::os::unix::process::CommandExt::process_group(&mut command, 0);
    command
        .spawn()
        .map(|_| ())
        .map_err(|e| format!("{BINARY}: {e}"))
}
//! The Bastion servers this app knows (D30): `local`, which the app starts,
//! and the ones the owner added. A server's name and URL live in
//! `servers.toml`; its token lives in the Keychain.

use std::path::{Path, PathBuf};

use bastion_protocol::{LOCAL, Server};
use serde::{Deserialize, Serialize};

pub const FILE_NAME: &str = "servers.toml";
/// The Keychain service each server's token is kept under.
const SERVICE: &str = "dev.tacoda.bastion.server";

/// Where the tokens are kept.
pub trait Vault: Send + Sync {
    fn get(&self, name: &str) -> Result<String, String>;
    fn set(&self, name: &str, token: &str) -> Result<(), String>;
    fn remove(&self, name: &str) -> Result<(), String>;
}

/// The macOS Keychain.
pub struct Keychain;

fn entry(name: &str) -> Result<keyring::Entry, String> {
    keyring::Entry::new(SERVICE, name).map_err(|e| e.to_string())
}

impl Vault for Keychain {
    fn get(&self, name: &str) -> Result<String, String> {
        entry(name)?
            .get_password()
            .map_err(|e| format!("{name}'s token: {e}"))
    }

    fn set(&self, name: &str, token: &str) -> Result<(), String> {
        entry(name)?.set_password(token).map_err(|e| e.to_string())
    }

    fn remove(&self, name: &str) -> Result<(), String> {
        match entry(name)?.delete_credential() {
            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
            Err(e) => Err(e.to_string()),
        }
    }
}

/// One added server as the file keeps it, without its token.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
struct Added {
    name: String,
    url: String,
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct File {
    #[serde(default)]
    server: Vec<Added>,
}

pub struct Servers {
    path: PathBuf,
    local: Server,
    vault: Box<dyn Vault>,
}

impl Servers {
    pub fn new(path: PathBuf, local: Server, vault: Box<dyn Vault>) -> Self {
        Servers { path, local, vault }
    }

    fn read(&self) -> Result<File, String> {
        match std::fs::read_to_string(&self.path) {
            Ok(text) => toml::from_str(&text).map_err(|e| format!("{}: {e}", self.path.display())),
            Err(_) => Ok(File::default()),
        }
    }

    fn write(&self, file: &File) -> Result<(), String> {
        let text = toml::to_string(file).map_err(|e| e.to_string())?;
        write_file(&self.path, &text)
    }

    /// `local` first, then the added servers in the order they were added.
    pub fn all(&self) -> Result<Vec<Server>, String> {
        let mut all = vec![self.local.clone()];
        for a in self.read()?.server {
            let token = self.vault.get(&a.name)?;
            all.push(Server {
                name: a.name,
                url: a.url,
                token,
            });
        }
        Ok(all)
    }

    pub fn add(&self, server: Server) -> Result<(), String> {
        let name = server.name.trim();
        let url = server.url.trim().trim_end_matches('/');
        if name.is_empty() || server.token.trim().is_empty() {
            return Err("a Bastion server needs a name, a URL and a token".into());
        }
        if !(url.starts_with("http://") || url.starts_with("https://")) {
            return Err(format!("{url} is not an http:// or https:// URL"));
        }
        let mut file = self.read()?;
        if name == LOCAL || file.server.iter().any(|s| s.name == name) {
            return Err(format!("there is already a Bastion server named {name}"));
        }
        self.vault.set(name, server.token.trim())?;
        file.server.push(Added {
            name: name.into(),
            url: url.into(),
        });
        self.write(&file)
    }

    pub fn remove(&self, name: &str) -> Result<(), String> {
        if name == LOCAL {
            return Err("local is the server this app runs; it cannot be removed".into());
        }
        let mut file = self.read()?;
        file.server.retain(|s| s.name != name);
        self.write(&file)?;
        self.vault.remove(name)
    }
}

fn write_file(path: &Path, text: &str) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(path, text).map_err(|e| format!("{}: {e}", path.display()))
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;
    use std::sync::Mutex;

    use super::*;

    #[derive(Default)]
    struct Memory(Mutex<HashMap<String, String>>);

    impl Vault for Memory {
        fn get(&self, name: &str) -> Result<String, String> {
            self.0
                .lock()
                .unwrap()
                .get(name)
                .cloned()
                .ok_or("none".into())
        }
        fn set(&self, name: &str, token: &str) -> Result<(), String> {
            self.0.lock().unwrap().insert(name.into(), token.into());
            Ok(())
        }
        fn remove(&self, name: &str) -> Result<(), String> {
            self.0.lock().unwrap().remove(name);
            Ok(())
        }
    }

    fn server(name: &str, url: &str) -> Server {
        Server {
            name: name.into(),
            url: url.into(),
            token: format!("{name}-token"),
        }
    }

    fn servers(dir: &Path) -> Servers {
        let local = server(LOCAL, "http://127.0.0.1:49190");
        Servers::new(dir.join(FILE_NAME), local, Box::new(Memory::default()))
    }

    fn scratch(tag: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("bastion-servers-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        dir
    }

    #[test]
    fn local_comes_first_and_an_added_server_keeps_its_token_out_of_the_file() {
        let dir = scratch("add");
        let s = servers(&dir);
        s.add(server("box", "https://box.example/")).unwrap();
        let all = s.all().unwrap();
        let names: Vec<&str> = all.iter().map(|s| s.name.as_str()).collect();
        assert_eq!(names, [LOCAL, "box"]);
        assert_eq!(
            (all[1].url.as_str(), all[1].token.as_str()),
            ("https://box.example", "box-token")
        );
        let file = std::fs::read_to_string(dir.join(FILE_NAME)).unwrap();
        assert!(!file.contains("box-token"), "{file}");
    }

    #[test]
    fn a_name_taken_a_bad_url_or_removing_local_is_refused() {
        let s = servers(&scratch("refuse"));
        s.add(server("box", "https://box.example")).unwrap();
        assert!(s.add(server("box", "https://other.example")).is_err());
        assert!(s.add(server(LOCAL, "https://other.example")).is_err());
        assert!(s.add(server("ftp", "ftp://box.example")).is_err());
        assert!(s.remove(LOCAL).is_err());
        s.remove("box").unwrap();
        assert_eq!(s.all().unwrap().len(), 1);
    }
}
