//! Calls to a Bastion server (PLAN.md D28): each command goes over HTTP by
//! the route table in `bastion-protocol`, with the server's bearer token.

use bastion_protocol::Server;
use bastion_protocol::routes::{self, Body};
use serde_json::{Map, Value};

/// One HTTP client for every call, so connections are kept.
pub fn http() -> reqwest::Client {
    reqwest::Client::new()
}

/// Call `cmd` on `server` with `args`, and return its answer, or the
/// server's refusal as text.
pub async fn call(http: reqwest::Client, server: Server, cmd: &'static str, args: Value) -> Result<Value, String> {
    let (method, path, body) = routes::route(cmd).ok_or_else(|| format!("{cmd} is not a server command"))?;
    let mut args = match args {
        Value::Object(map) => map,
        _ => Map::new(),
    };
    let path = fill(path, &mut args);
    let body = match body {
        Body::Empty => None,
        Body::Field(name) => args.remove(name),
        Body::Rest => Some(Value::Object(args)),
    };
    let url = format!("{}{path}", server.url.trim_end_matches('/'));
    let method = reqwest::Method::from_bytes(method.as_bytes()).map_err(|e| e.to_string())?;
    let mut request = http.request(method, url).bearer_auth(&server.token);
    if let Some(body) = body {
        request = request.json(&body);
    }
    let unreachable = |_| format!("The Bastion server {} at {} cannot be reached.", server.name, server.url);
    let response = request.send().await.map_err(unreachable)?;
    let ok = response.status().is_success();
    let text = response.text().await.unwrap_or_default();
    answer(ok, &text)
}

/// A success's value, or a refusal's text: `{ "error": text }`, or the
/// typed error as it is.
fn answer(ok: bool, text: &str) -> Result<Value, String> {
    let value: Value = serde_json::from_str(text).unwrap_or(Value::Null);
    if ok {
        return Ok(value);
    }
    match value.get("error").cloned().unwrap_or(value) {
        Value::String(why) => Err(why),
        other => Err(other.to_string()),
    }
}

/// Put each `{name}` argument into the path, and take it out of the args.
fn fill(template: &str, args: &mut Map<String, Value>) -> String {
    let mut path = template.to_string();
    while let Some(start) = path.find('{') {
        let end = start + path[start..].find('}').unwrap_or(0);
        let name = path[start + 1..end].to_string();
        let value = match args.remove(&name) {
            Some(Value::String(s)) => s,
            Some(other) => other.to_string(),
            None => String::new(),
        };
        path.replace_range(start..=end, &encode(&value));
    }
    path
}

/// A path segment, percent-encoded.
fn encode(segment: &str) -> String {
    let kept = |b: u8| b.is_ascii_alphanumeric() || b"-._~".contains(&b);
    segment
        .bytes()
        .map(|b| if kept(b) { (b as char).to_string() } else { format!("%{b:02X}") })
        .collect()
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn path_arguments_fill_the_path_and_leave_the_body() {
        let mut args = json!({ "id": "j1", "text": "a b" }).as_object().unwrap().clone();
        assert_eq!(fill("/jobs/{id}/comment", &mut args), "/jobs/j1/comment");
        assert_eq!(Value::Object(args), json!({ "text": "a b" }));
        let mut args = json!({ "workspace": "my repo", "number": 7 }).as_object().unwrap().clone();
        assert_eq!(fill("/issues/{workspace}/{number}/job", &mut args), "/issues/my%20repo/7/job");
    }

    #[test]
    fn a_refusal_reads_as_its_text() {
        assert_eq!(answer(true, r#"{"a":1}"#), Ok(json!({ "a": 1 })));
        assert_eq!(answer(false, r#"{"error":"no"}"#), Err("no".into()));
        assert_eq!(answer(false, r#"{"code":7}"#), Err(r#"{"code":7}"#.into()));
    }
}

//! Each Bastion server's pushes (PLAN.md D29): one `GET /events` stream per
//! server, read again with `Last-Event-ID` after it drops.

use std::time::Duration;

use bastion_protocol::{Change, Server};
use futures_util::{SinkExt, Stream, StreamExt};
use iced::Subscription;

/// What a server's stream says.
#[derive(Clone, Debug)]
pub enum Feed {
    /// The stream is open: the server answers.
    Up,
    /// The stream dropped: the server cannot be reached until it is back.
    Down,
    Change(Change),
    /// Changes were missed: read everything again.
    Resync,
}

/// The pushes of every server in `servers`, each tagged with its name.
pub fn follow(servers: &[Server]) -> Subscription<(String, Feed)> {
    let each = servers.iter().map(|s| {
        let key = (s.name.clone(), s.url.clone(), s.token.clone());
        Subscription::run_with(key, stream)
    });
    Subscription::batch(each)
}

type Key = (String, String, String);

fn stream(key: &Key) -> impl Stream<Item = (String, Feed)> + use<> {
    let (name, url, token) = key.clone();
    let server = Server { name, url, token };
    iced::stream::channel(64, async move |mut out| {
        let http = reqwest::Client::new();
        let mut last = None;
        loop {
            let _ = read(&http, &server, &mut last, &mut out).await;
            let _ = out.send((server.name.clone(), Feed::Down)).await;
            tokio::time::sleep(Duration::from_secs(1)).await;
        }
    })
}

type Out = futures_util::channel::mpsc::Sender<(String, Feed)>;

/// Read one connection until it ends.
async fn read(http: &reqwest::Client, server: &Server, last: &mut Option<String>, out: &mut Out) -> Result<(), String> {
    let url = format!("{}/events", server.url.trim_end_matches('/'));
    let mut request = http.get(url).bearer_auth(&server.token);
    if let Some(id) = last.as_deref() {
        request = request.header("Last-Event-ID", id);
    }
    let response = request.send().await.map_err(|e| e.to_string())?;
    if !response.status().is_success() {
        return Err(format!("events: status {}", response.status()));
    }
    let send = |feed| (server.name.clone(), feed);
    let _ = out.send(send(Feed::Up)).await;
    // A reconnect may have missed changes the server did not replay.
    if last.is_some() {
        let _ = out.send(send(Feed::Resync)).await;
    }
    let mut body = response.bytes_stream();
    let mut buffer = String::new();
    while let Some(chunk) = body.next().await {
        buffer.push_str(&String::from_utf8_lossy(&chunk.map_err(|e| e.to_string())?));
        while let Some(end) = buffer.find("\n\n") {
            let block: String = buffer.drain(..end + 2).collect();
            for feed in parse(&block, last) {
                let _ = out.send(send(feed)).await;
            }
        }
    }
    Ok(())
}

/// One server-sent event: an id and a change, or a request to read again.
fn parse(block: &str, last: &mut Option<String>) -> Vec<Feed> {
    let mut feeds = Vec::new();
    for line in block.lines() {
        if let Some(id) = line.strip_prefix("id: ") {
            *last = Some(id.to_string());
        } else if line == "event: resync" {
            feeds.push(Feed::Resync);
        } else if let Some(change) = line.strip_prefix("data: ").and_then(|d| serde_json::from_str(d).ok()) {
            feeds.push(Feed::Change(change));
        }
    }
    feeds
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_event_keeps_its_id_and_a_resync_asks_to_read_again() {
        let mut last = None;
        let feeds = parse("id: 7\ndata: {\"kind\":\"job\",\"id\":\"j1\"}\n\n", &mut last);
        assert_eq!(last.as_deref(), Some("7"));
        assert!(matches!(&feeds[..], [Feed::Change(Change::Job { id })] if id == "j1"));
        assert!(matches!(&parse("event: resync\ndata: {}\n\n", &mut last)[..], [Feed::Resync]));
        assert!(parse(": keep-alive\n\n", &mut last).is_empty());
    }
}

//! D4's theme: one dark theme, purple as the main color. The same tokens as
//! the Leptos pages' `styles.css`, as iced styles.

use iced::widget::{button, container, pick_list, text_input};
use iced::{Background, Border, Color, Theme};

const fn hex(rgb: u32) -> Color {
    let byte = |shift: u32| ((rgb >> shift) & 0xff) as f32 / 255.0;
    Color { r: byte(16), g: byte(8), b: byte(0), a: 1.0 }
}

pub const BG: Color = hex(0x0f0d17);
pub const PANEL: Color = hex(0x19162a);
pub const INK: Color = hex(0xece9f5);
pub const MUTED: Color = hex(0xa39cb8);
pub const LINE: Color = hex(0x2c2742);
pub const PRIMARY: Color = hex(0x7c3aed);
pub const PRIMARY_HOVER: Color = hex(0x6d28d9);
pub const LINK: Color = hex(0xc4b5fd);
pub const OK: Color = hex(0x4ade80);
pub const BAD: Color = hex(0xf87171);
pub const WARN: Color = hex(0xfbbf24);

fn rounded(radius: f32) -> Border {
    Border { radius: radius.into(), ..Border::default() }
}

fn lined(radius: f32) -> Border {
    Border { radius: radius.into(), width: 1.0, color: LINE }
}

/// The window behind every page.
pub fn page(_: &Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(BG)),
        text_color: Some(INK),
        ..container::Style::default()
    }
}

/// The sidebar: the panel color, a line on its right.
pub fn sidebar(_: &Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(PANEL)),
        border: Border { width: 1.0, color: LINE, ..Border::default() },
        ..container::Style::default()
    }
}

/// A section or a row: the panel color in a rounded, lined box.
pub fn panel(_: &Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(PANEL)),
        border: lined(12.0),
        ..container::Style::default()
    }
}

/// The dark veil behind a dialog.
pub fn veil(_: &Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(Color { a: 0.6, ..Color::BLACK })),
        ..container::Style::default()
    }
}

/// A sidebar entry: purple when its page is shown, a line on hover.
pub fn nav(here: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_, status| {
        let background = match (here, status) {
            (true, _) => Some(Background::Color(PRIMARY)),
            (false, button::Status::Hovered | button::Status::Pressed) => Some(Background::Color(LINE)),
            _ => None,
        };
        let text_color = if here { Color::WHITE } else { INK };
        button::Style { background, text_color, border: rounded(8.0), ..button::Style::default() }
    }
}

/// The main action: white on purple.
pub fn primary(_: &Theme, status: button::Status) -> button::Style {
    let fill = if status == button::Status::Hovered { PRIMARY_HOVER } else { PRIMARY };
    button::Style {
        background: Some(Background::Color(fill)),
        text_color: Color::WHITE,
        border: rounded(8.0),
        ..button::Style::default()
    }
}

/// Any other button: a lined box that fills on hover.
pub fn secondary(_: &Theme, status: button::Status) -> button::Style {
    let background = (status == button::Status::Hovered).then_some(Background::Color(LINE));
    button::Style { background, text_color: INK, border: lined(8.0), ..button::Style::default() }
}

/// A plain button with muted text, as Cancel.
pub fn quiet(_: &Theme, status: button::Status) -> button::Style {
    let background = (status == button::Status::Hovered).then_some(Background::Color(LINE));
    button::Style { background, text_color: MUTED, border: rounded(8.0), ..button::Style::default() }
}

pub fn select(_: &Theme, _: pick_list::Status) -> pick_list::Style {
    pick_list::Style {
        text_color: INK,
        placeholder_color: MUTED,
        handle_color: MUTED,
        background: Background::Color(BG),
        border: lined(4.0),
    }
}

pub fn field(_: &Theme, status: text_input::Status) -> text_input::Style {
    let edge = if matches!(status, text_input::Status::Focused { .. }) { PRIMARY } else { LINE };
    text_input::Style {
        background: Background::Color(BG),
        border: Border { color: edge, ..lined(4.0) },
        icon: MUTED,
        placeholder: MUTED,
        value: INK,
        selection: PRIMARY,
    }
}

