//! Where the window is, and the sidebar's pages.

use crate::icons;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Route {
    Jobs,
    NewRequest,
    Job(String),
    Constraints,
    Capabilities,
    Audit,
    Evals,
    Eval(String),
    Engine,
    Workflows,
    Settings,
}

/// The sidebar's pages. A job and New request belong to Jobs.
pub const PAGES: [(Route, &str, &str); 8] = [
    (Route::Jobs, "Jobs", icons::JOBS),
    (Route::Workflows, "Workflows", icons::WORKFLOWS),
    (Route::Constraints, "Constraints", icons::CONSTRAINTS),
    (Route::Capabilities, "Capabilities", icons::CAPABILITIES),
    (Route::Audit, "Audit Log", icons::AUDIT),
    (Route::Evals, "Evals", icons::EVALS),
    (Route::Engine, "Engine", icons::ENGINE),
    (Route::Settings, "Settings", icons::SETTINGS),
];

impl Route {
    /// The sidebar entry this page sits under.
    pub fn section(&self) -> Route {
        match self {
            Route::NewRequest | Route::Job(_) => Route::Jobs,
            Route::Eval(_) => Route::Evals,
            other => other.clone(),
        }
    }

    /// A page about one Bastion server shows the server picker (D30).
    pub fn about_one_server(&self) -> bool {
        !matches!(self, Route::Jobs | Route::NewRequest | Route::Job(_))
    }

    pub fn title(&self) -> &'static str {
        let section = self.section();
        PAGES.iter().find(|(r, _, _)| *r == section).map_or("", |(_, title, _)| title)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_job_sits_under_jobs_and_shows_no_server_picker() {
        let job = Route::Job("j1".into());
        assert_eq!(job.section(), Route::Jobs);
        assert_eq!(job.title(), "Jobs");
        assert!(!job.about_one_server());
        assert!(Route::Settings.about_one_server());
        assert_eq!(Route::Eval("e1".into()).title(), "Evals");
    }
}

//! What the window does before its first page: start or attach to the
//! `local` Bastion server, and read the servers the owner added. The files
//! sit where the Tauri app kept them, so both clients share them until G4.

use std::path::{Path, PathBuf};

use bastion_protocol::Server;

use crate::local;
use crate::profile::{self, Profiles};
use crate::servers::{self, Keychain, Servers};

/// The checkout this build came from, which holds `worker-compose.yaml`.
// ponytail: a build-time path; packaging the stack replaces it (PLAN.md A13).
const CHECKOUT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");
const IDENTIFIER: &str = "dev.tacoda.bastion";

fn home() -> PathBuf {
    PathBuf::from(std::env::var_os("HOME").unwrap_or_default())
}

/// Where the app's files live: Application Support on macOS, the XDG
/// directories elsewhere, as Tauri put them.
fn dir(xdg: &str, fallback: &str) -> PathBuf {
    if cfg!(target_os = "macos") {
        return home().join("Library/Application Support").join(IDENTIFIER);
    }
    let base = std::env::var_os(xdg).map_or_else(|| home().join(fallback), PathBuf::from);
    base.join(IDENTIFIER)
}

pub fn config_dir() -> PathBuf {
    dir("XDG_CONFIG_HOME", ".config")
}

fn data_dir() -> PathBuf {
    dir("XDG_DATA_HOME", ".local/share")
}

/// The servers this app knows, around the `local` one.
pub fn servers(local: Server) -> Servers {
    Servers::new(config_dir().join(servers::FILE_NAME), local, Box::new(Keychain))
}

/// Start or attach to `local`, then list every server, `local` first.
/// Blocks until `local` answers, so it runs off the window's thread.
pub fn start() -> Result<Vec<Server>, String> {
    let checkout = Path::new(CHECKOUT).canonicalize().map_err(|e| e.to_string())?;
    let profiles = Profiles::load_or_create(&config_dir().join(profile::FILE_NAME), checkout)?;
    let local = local::start(profiles.active(), &data_dir().join("server"))?;
    servers(local).all()
}

//! The shell (PLAN.md G1): the sidebar, the page it shows, the server
//! picker, each server's pushes, and the question on quit while the stack
//! runs.

use std::collections::BTreeSet;

use bastion_protocol::{Change, LOCAL, Server, StackState, StackStatus, command};
use iced::widget::{Column, button, center, column, container, opaque, pick_list, row, stack, text};
use iced::{Element, Fill, Subscription, Task, window};
use serde_json::{Value, json};

use crate::events::{self, Feed};
use crate::route::{PAGES, Route};
use crate::{client, icons, start, theme};

#[derive(Clone, Debug)]
pub enum Message {
    Started(Result<Vec<Server>, String>),
    Go(Route),
    Choose(String),
    Feed((String, Feed)),
    CloseRequested,
    StackRunning(bool),
    Quit { stop_stack: bool },
    Stay,
}

pub struct App {
    http: reqwest::Client,
    servers: Vec<Server>,
    current: String,
    route: Route,
    /// Servers whose stream is down, so what was read from them may be stale.
    down: BTreeSet<String>,
    /// The last push, shown until the pages that use it are built (G2).
    last_push: Option<String>,
    asking: bool,
    problem: Option<String>,
}

impl App {
    pub fn new() -> (Self, Task<Message>) {
        let app = App {
            http: client::http(),
            servers: vec![],
            current: LOCAL.into(),
            route: Route::Jobs,
            down: BTreeSet::new(),
            last_push: None,
            asking: false,
            problem: None,
        };
        let started = async { tokio::task::spawn_blocking(start::start).await.map_err(|e| e.to_string())? };
        (app, Task::perform(started, Message::Started))
    }

    fn server(&self, name: &str) -> Option<Server> {
        self.servers.iter().find(|s| s.name == name).cloned()
    }

    /// Call `cmd` on the server named `on`, and map its answer.
    fn call(&self, on: &str, cmd: &'static str, args: Value, then: fn(Result<Value, String>) -> Message) -> Task<Message> {
        let Some(server) = self.server(on) else {
            return Task::none();
        };
        Task::perform(client::call(self.http.clone(), server, cmd, args), then)
    }

    pub fn update(&mut self, message: Message) -> Task<Message> {
        match message {
            Message::Started(Ok(all)) => self.servers = all,
            Message::Started(Err(why)) => self.problem = Some(why),
            Message::Go(route) => self.route = route,
            Message::Choose(name) => self.current = name,
            Message::Feed((server, feed)) => self.on_feed(server, feed),
            Message::CloseRequested => return self.on_close(),
            Message::StackRunning(true) => self.asking = true,
            Message::StackRunning(false) => return iced::exit(),
            Message::Quit { stop_stack } => return self.quit(stop_stack),
            Message::Stay => self.asking = false,
        }
        Task::none()
    }

    fn on_feed(&mut self, server: String, feed: Feed) {
        match feed {
            Feed::Up => {
                self.down.remove(&server);
            }
            Feed::Down => {
                self.down.insert(server);
            }
            Feed::Resync => self.last_push = Some(format!("{server}: read everything again")),
            Feed::Change(change) => self.last_push = Some(format!("{server}: {}", describe(&change))),
        }
    }

    /// The stack belongs to the server (D27), so a quit asks only while it runs.
    fn on_close(&self) -> Task<Message> {
        if self.server(LOCAL).is_none() {
            return iced::exit();
        }
        self.call(LOCAL, command::STACK_STATUS, json!({}), |answer| {
            let status = answer.ok().and_then(|v| serde_json::from_value::<StackStatus>(v).ok());
            Message::StackRunning(status.is_some_and(|s| s.state == StackState::Running))
        })
    }

    fn quit(&self, stop_stack: bool) -> Task<Message> {
        if !stop_stack {
            return iced::exit();
        }
        self.call(LOCAL, command::STACK_STOP, json!({}), |_| Message::StackRunning(false))
    }

    pub fn subscription(&self) -> Subscription<Message> {
        let pushes = events::follow(&self.servers).map(Message::Feed);
        let closes = window::close_requests().map(|_| Message::CloseRequested);
        Subscription::batch([pushes, closes])
    }

    pub fn view(&self) -> Element<'_, Message> {
        let main = column![self.picker(), self.page()].spacing(16).padding(32).width(Fill);
        let shell = container(row![self.sidebar(), main]).width(Fill).height(Fill).style(theme::page);
        if !self.asking {
            return shell.into();
        }
        stack![shell, opaque(container(center(quit_dialog())).style(theme::veil))].into()
    }

    fn sidebar(&self) -> Element<'_, Message> {
        let here = self.route.section();
        let mut items = vec![text("Bastion").size(18).font(bold()).into()];
        for (route, label, glyph) in PAGES {
            let on = route == here;
            let color = if on { iced::Color::WHITE } else { theme::INK };
            let entry = row![icons::icon(glyph, color), text(label)].spacing(8).align_y(iced::Center);
            items.push(button(entry).width(Fill).padding([6, 8]).style(theme::nav(on)).on_press(Message::Go(route)).into());
        }
        let list = Column::with_children(items).spacing(4);
        let body = column![list, iced::widget::space::vertical(), self.reach()];
        container(body).width(200).height(Fill).padding(12).style(theme::sidebar).into()
    }

    /// Each server and whether its stream is up.
    fn reach(&self) -> Element<'_, Message> {
        let rows = self.servers.iter().map(|s| {
            let up = !self.down.contains(&s.name);
            let mark = text(if up { "●" } else { "○" }).color(if up { theme::OK } else { theme::BAD });
            row![mark, text(&s.name).size(12).color(theme::MUTED)].spacing(6).into()
        });
        Column::with_children(rows).spacing(2).into()
    }

    /// Which Bastion server a page about one server shows (D30).
    fn picker(&self) -> Element<'_, Message> {
        if !self.route.about_one_server() {
            return column![].into();
        }
        let names: Vec<String> = self.servers.iter().map(|s| s.name.clone()).collect();
        let pick = pick_list(names, Some(self.current.clone()), Message::Choose).style(theme::select);
        row![text("Bastion server").color(theme::MUTED), pick].spacing(8).align_y(iced::Center).into()
    }

    fn page(&self) -> Element<'_, Message> {
        let title = text(self.route.title()).size(24).font(bold());
        let note = match (&self.problem, &self.last_push) {
            (Some(why), _) => text(why.clone()).color(theme::BAD),
            (None, Some(push)) => text(format!("Last push: {push}")).color(theme::MUTED),
            (None, None) => text("This page is built in G2.").color(theme::MUTED),
        };
        column![title, note].spacing(12).into()
    }
}

fn bold() -> iced::Font {
    iced::Font { weight: iced::font::Weight::Bold, ..iced::Font::DEFAULT }
}

fn describe(change: &Change) -> String {
    match change {
        Change::Job { id } if id.is_empty() => "every job".into(),
        Change::Job { id } => format!("job {id}"),
        Change::Engine { status } => format!("engine {:?}", status.link),
        Change::Console => "the console".into(),
    }
}

fn quit_dialog<'a>() -> Element<'a, Message> {
    let buttons = row![
        button("Keep it running").padding([8, 12]).style(theme::primary).on_press(Message::Quit { stop_stack: false }),
        button("Stop the stack").padding([8, 12]).style(theme::secondary).on_press(Message::Quit { stop_stack: true }),
        button("Cancel").padding([8, 12]).style(theme::quiet).on_press(Message::Stay),
    ]
    .spacing(8);
    let body = column![
        text("The stack is running").size(18).font(bold()),
        text("Stop it with the app, or keep it running for the next start to attach to?").color(theme::MUTED),
        buttons,
    ]
    .spacing(12)
    .max_width(400);
    container(body).padding(20).style(theme::panel).into()
}

