                        }).collect_view()}
                        {transcript.filter(|t| !t.is_empty()).map(|t| view! {
                            <details>
                                <summary class="cursor-pointer text-xs text-muted">{format!("Latest turn ({} messages)", t.len())}</summary>
                                <ol class="m-0 grid gap-2 p-0 pl-5 text-xs">
                                    {t.into_iter().map(|line| view! {
