//! The factory's settings (A7, D33): the oversight presets, the model per
//! stage, where a change goes and where requests come from; each step's
//! dial; and every version of the settings with Restore.

use bastion_protocol::{DialsView, ModelOption, PipelineDials, SettingsView, VersionView, command};
use iced::widget::{Column, button, column, pick_list, row, text};
use iced::{Element, Fill, Task};
use serde_json::{Value, json};

use super::{card, small};
use crate::app::Message;
use crate::client::Ask;
use crate::pages::{Choice, Ctx, ago, labeled};
use crate::theme;

const PRESETS: [(&str, &str); 3] = [("lights_on", "lights-on"), ("dim", "dim"), ("dark", "dark")];
const FORGES: [(&str, &str); 2] = [("local", "Merged here, into the workspace's branch"), ("github", "Pushed and opened as a GitHub pull request")];
const TRACKERS: [(&str, &str); 2] = [("none", "Only what you type"), ("github_issues", "Also GitHub issues")];

#[derive(Default)]
pub struct State {
    settings: Option<SettingsView>,
    models: Vec<Choice>,
    dials: Option<DialsView>,
    versions: Vec<VersionView>,
    note: String,
}

/// Which setting a pick changes.
#[derive(Clone, Copy, Debug)]
pub enum Pick {
    PlanModel,
    BuildModel,
    Forge,
    Tracker,
}

#[derive(Clone, Debug)]
pub enum Msg {
    Settings(Result<SettingsView, String>),
    Models(Result<Vec<ModelOption>, String>),
    Dials(Result<DialsView, String>),
    Versions(Result<Vec<VersionView>, String>),
    Set(Pick, Choice),
    Preset(&'static str),
    Dial(String, String),
    Restore(u64),
    Done(Result<Value, String>),
}

fn wrap(msg: Msg) -> Message {
    Message::Settings(super::Msg::Factory(msg))
}

fn task<T>(ctx: &Ctx, ask: Ask, then: fn(Result<T, String>) -> Msg) -> Task<Message>
where
    T: serde::de::DeserializeOwned + Send + 'static,
{
    ctx.task(&ctx.current, ask, then).map(wrap)
}

pub fn load(ctx: &Ctx) -> Task<Message> {
    Task::batch([
        task(ctx, Ask::bare(command::SETTINGS), Msg::Settings),
        task(ctx, Ask::bare(command::MODELS), Msg::Models),
        task(ctx, Ask::bare(command::DIALS), Msg::Dials),
        task(ctx, Ask::bare(command::SETTINGS_HISTORY), Msg::Versions),
    ])
}

/// Each model as a choice: `provider/id`, labeled with its name.
fn model_choices(models: Vec<ModelOption>) -> Vec<Choice> {
    models.into_iter().map(|m| Choice::new(&format!("{}/{}", m.provider, m.id), &format!("{} ({})", m.name, m.provider))).collect()
}

/// The settings with one pick applied.
fn apply(mut s: SettingsView, pick: Pick, choice: &str) -> SettingsView {
    let model = || {
        let (p, m) = choice.split_once('/').unwrap_or_default();
        (p.to_string(), m.to_string())
    };
    match pick {
        Pick::PlanModel => (s.plan_provider, s.plan_model) = model(),
        Pick::BuildModel => (s.build_provider, s.build_model) = model(),
        Pick::Forge => s.forge = choice.into(),
        Pick::Tracker => s.tracker = choice.into(),
    }
    s
}

fn keep<T>(slot: &mut T, note: &mut String, answer: Result<T, String>) {
    match answer {
        Ok(v) => *slot = v,
        Err(e) => *note = e,
    }
}

fn send(ctx: &Ctx, cmd: &'static str, args: Value) -> Task<Message> {
    task(ctx, Ask { cmd, args }, Msg::Done)
}

pub fn update(state: &mut State, msg: Msg, ctx: &Ctx) -> Task<Message> {
    let note = &mut state.note;
    match msg {
        Msg::Settings(a) => keep(&mut state.settings, note, a.map(Some)),
        Msg::Models(a) => keep(&mut state.models, note, a.map(model_choices)),
        Msg::Dials(a) => keep(&mut state.dials, note, a.map(Some)),
        Msg::Versions(a) => keep(&mut state.versions, note, a),
        Msg::Set(pick, choice) => {
            let Some(s) = state.settings.clone() else { return Task::none() };
            return send(ctx, command::SETTINGS_SET, json!({ "settings": apply(s, pick, &choice.id) }));
        }
        Msg::Preset(p) => return send(ctx, command::SETTINGS_PRESET, json!({ "preset": p })),
        Msg::Dial(stage, dial) => return send(ctx, command::DIALS_SET, json!({ "stage": stage, "dial": dial })),
        Msg::Restore(version) => return send(ctx, command::SETTINGS_RESTORE, json!({ "version": version })),
        Msg::Done(Ok(_)) => {
            state.note = "Saved as a new version.".into();
            return load(ctx);
        }
        Msg::Done(Err(e)) => state.note = e,
    }
    Task::none()
}

fn choices(all: &[(&str, &str)]) -> Vec<Choice> {
    all.iter().map(|(id, name)| Choice::new(id, name)).collect()
}

fn picker<'a>(label: &'a str, options: Vec<Choice>, current: String, pick: Pick) -> Element<'a, Message> {
    let shown = options.iter().find(|c| c.id == current).cloned();
    let list = pick_list(options, shown, move |c| wrap(Msg::Set(pick, c))).style(theme::select).width(Fill);
    labeled(label, list)
}

fn factory(state: &State) -> Element<'_, Message> {
    let presets = PRESETS.iter().map(|(id, label)| small(label, Some(wrap(Msg::Preset(id)))));
    let mut body = column![row![text("Oversight:").size(13).color(theme::MUTED)].extend(presets).spacing(8).align_y(iced::Center)];
    if let Some(s) = &state.settings {
        let models = &state.models;
        body = body
            .push(row![
                picker("Plan model", models.clone(), format!("{}/{}", s.plan_provider, s.plan_model), Pick::PlanModel),
                picker("Build model", models.clone(), format!("{}/{}", s.build_provider, s.build_model), Pick::BuildModel),
            ].spacing(16))
            .push(row![
                picker("Where a reviewed change goes", choices(&FORGES), s.forge.clone(), Pick::Forge),
                picker("Where requests can come from", choices(&TRACKERS), s.tracker.clone(), Pick::Tracker),
            ].spacing(16));
    }
    card("Factory", body.push(text(&state.note).size(13).color(theme::MUTED)))
}

fn pipeline<'a>(title: &str, p: &PipelineDials) -> Element<'a, Message> {
    let steps = p.steps.iter().map(|s| {
        let on = s.dial == "lights_on";
        let label = format!("{} · {}", s.stage.replace('_', " "), if on { "lights-on" } else { "dark" });
        let flip = wrap(Msg::Dial(s.stage.clone(), if on { "dark" } else { "lights_on" }.into()));
        let look = if on { theme::secondary } else { theme::quiet };
        button(text(label).size(13)).padding([4, 10]).style(look).on_press(flip).into()
    });
    column![text(format!("{title}: {}", p.level.replace('_', "-"))).size(13), row(steps).spacing(8).wrap()].spacing(8).into()
}

fn oversight(state: &State) -> Element<'_, Message> {
    let lede = "A lights-on step waits for you to approve its result or send it back. A dark step goes on at once. A pipeline is lights-on when every step is, dim when a step up to the merge is, and dark when none is.";
    let mut body = column![text(lede).size(13).color(theme::MUTED)];
    if let Some(d) = &state.dials {
        body = body.push(pipeline("Short pipeline", &d.short)).push(pipeline("Full pipeline", &d.full));
    }
    card("Oversight", body)
}

fn history(state: &State) -> Element<'_, Message> {
    let newest = state.versions.first().map(|v| v.version);
    let rows = state.versions.iter().map(|v| {
        let restore = (newest != Some(v.version)).then(|| small("Restore", Some(wrap(Msg::Restore(v.version)))));
        row![text(format!("v{} · {}", v.version, ago(v.at))).size(13).color(theme::MUTED).width(140), text(v.note.clone()).size(13).width(Fill)]
            .push_maybe(restore)
            .spacing(8)
            .align_y(iced::Center)
            .into()
    });
    card("History", Column::with_children(rows))
}

pub fn view(state: &State) -> [Element<'_, Message>; 3] {
    [factory(state), oversight(state), history(state)]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_pick_sets_one_setting_and_keeps_the_rest() {
        let s = SettingsView { plan_provider: "openai".into(), plan_model: "gpt-5-mini".into(), forge: "github".into(), ..SettingsView::default() };
        let picked = apply(s.clone(), Pick::PlanModel, "localfake/echo-1");
        assert_eq!((picked.plan_provider.as_str(), picked.plan_model.as_str(), picked.forge.as_str()), ("localfake", "echo-1", "github"));
        assert_eq!(apply(s, Pick::Tracker, "github_issues").tracker, "github_issues");
    }
}

//! Model providers (D34) and OpenAI-compatible hosts (K3). A key is sent
//! once, to the stack's vault, and never shown again. OpenAI Codex signs in
//! with a ChatGPT plan by a device code the page polls until it ends.

use std::collections::BTreeMap;
use std::time::Duration;

use bastion_protocol::{HostView, ProviderView, SignIn, command};
use iced::widget::{Column, button, column, row, text, text_input};
use iced::{Element, Fill, Task};
use serde_json::{Value, json};

use super::{card, small};
use crate::app::Message;
use crate::client::Ask;
use crate::pages::Ctx;
use crate::theme;

#[derive(Default)]
pub struct State {
    providers: Vec<ProviderView>,
    /// What the owner typed as each provider's key, until Set sends it.
    keys: BTreeMap<String, String>,
    signing_in: Option<SignIn>,
    hosts: Vec<HostView>,
    new_host: HostView,
    note: String,
}

#[derive(Clone, Copy, Debug)]
pub enum HostField {
    Id,
    Name,
    Url,
}

#[derive(Clone, Debug)]
pub enum Msg {
    Providers(Result<Vec<ProviderView>, String>),
    Hosts(Result<Vec<HostView>, String>),
    Key(String, String),
    SetKey(String),
    RemoveKey(String),
    SignIn,
    Started(Result<SignIn, String>),
    Polled(Result<String, String>),
    SignOut,
    HostField(HostField, String),
    AddHost,
    RemoveHost(String),
    Done(Result<Value, String>),
}

fn wrap(msg: Msg) -> Message {
    Message::Settings(super::Msg::Providers(msg))
}

fn task<T>(ctx: &Ctx, ask: Ask, then: fn(Result<T, String>) -> Msg) -> Task<Message>
where
    T: serde::de::DeserializeOwned + Send + 'static,
{
    ctx.task(&ctx.current, ask, then).map(wrap)
}

pub fn load(ctx: &Ctx) -> Task<Message> {
    Task::batch([task(ctx, Ask::bare(command::PROVIDERS), Msg::Providers), task(ctx, Ask::bare(command::HOSTS), Msg::Hosts)])
}

/// The host list with `host` added, or with the host of that id replaced.
fn with_host(mut hosts: Vec<HostView>, host: HostView) -> Vec<HostView> {
    hosts.retain(|h| h.id != host.id);
    hosts.push(host);
    hosts
}

fn save_hosts(ctx: &Ctx, hosts: Vec<HostView>) -> Task<Message> {
    task(ctx, Ask { cmd: command::HOSTS_SET, args: json!({ "hosts": hosts }) }, Msg::Done)
}

/// Wait the sign-in's interval, then ask how it went.
fn poll(ctx: &Ctx, s: &SignIn) -> Task<Message> {
    let (wait, ask) = (Duration::from_secs(s.interval.max(1)), Ask { cmd: command::CODEX_SIGN_IN_POLL, args: json!({ "login_id": s.login_id }) });
    let read = ctx.clone().get::<String>(ctx.current.clone(), ask);
    Task::perform(
        async move {
            tokio::time::sleep(wait).await;
            read.await
        },
        |r| wrap(Msg::Polled(r)),
    )
}

fn on_polled(state: &mut State, ctx: &Ctx, answer: Result<String, String>) -> Task<Message> {
    match answer.as_deref() {
        Ok("pending") => return state.signing_in.as_ref().map_or_else(Task::none, |s| poll(ctx, s)),
        Ok("ok") => state.note.clear(),
        Ok(other) => state.note = format!("The ChatGPT sign-in ended: {other}. Try again."),
        Err(e) => state.note = e.clone(),
    }
    state.signing_in = None;
    load(ctx)
}

fn on_host(state: &mut State, field: HostField, value: String) {
    let h = &mut state.new_host;
    match field {
        HostField::Id => h.id = value,
        HostField::Name => h.name = value,
        HostField::Url => h.api_url = value,
    }
}

pub fn update(state: &mut State, msg: Msg, ctx: &Ctx) -> Task<Message> {
    match msg {
        Msg::Providers(Ok(all)) => state.providers = all,
        Msg::Hosts(Ok(all)) => state.hosts = all,
        Msg::Providers(Err(e)) | Msg::Hosts(Err(e)) | Msg::Done(Err(e)) | Msg::Started(Err(e)) => state.note = e,
        Msg::Key(id, key) => {
            state.keys.insert(id, key);
        }
        Msg::SetKey(id) => {
            let key = state.keys.remove(&id).unwrap_or_default();
            return task(ctx, Ask { cmd: command::PROVIDER_KEY_SET, args: json!({ "id": id, "key": key }) }, Msg::Done);
        }
        Msg::RemoveKey(id) => return task(ctx, Ask { cmd: command::PROVIDER_KEY_REMOVE, args: json!({ "id": id }) }, Msg::Done),
        Msg::SignIn => return task(ctx, Ask::bare(command::CODEX_SIGN_IN), Msg::Started),
        Msg::Started(Ok(s)) => {
            let next = poll(ctx, &s);
            state.signing_in = Some(s);
            return next;
        }
        Msg::Polled(answer) => return on_polled(state, ctx, answer),
        Msg::SignOut => return task(ctx, Ask::bare(command::CODEX_SIGN_OUT), Msg::Done),
        Msg::HostField(f, v) => on_host(state, f, v),
        Msg::AddHost => {
            let host = std::mem::take(&mut state.new_host);
            return save_hosts(ctx, with_host(state.hosts.clone(), host));
        }
        Msg::RemoveHost(id) => return save_hosts(ctx, state.hosts.iter().filter(|h| h.id != id).cloned().collect()),
        Msg::Done(Ok(_)) => {
            state.note.clear();
            return load(ctx);
        }
    }
    Task::none()
}

/// A provider's name with a mark for whether turns can run on it.
fn name<'a>(p: &ProviderView) -> Element<'a, Message> {
    let ok = p.ready || p.source != "none";
    let mark = text(if ok { "✓" } else { "!" }).color(if ok { theme::OK } else { theme::WARN });
    row![mark, text(p.name.clone()).font(theme::BOLD)].spacing(6).into()
}

fn key_status(p: &ProviderView) -> &'static str {
    match p.source.as_str() {
        "secret" => "key set here",
        "env" => "key from the stack's environment",
        _ if p.ready => "no key needed",
        _ => "no key",
    }
}

fn key_row<'a>(state: &State, p: &ProviderView) -> Element<'a, Message> {
    let typed = state.keys.get(&p.id).cloned().unwrap_or_default();
    let id = p.id.clone();
    let field = text_input("API key", &typed).secure(true).on_input(move |k| wrap(Msg::Key(id.clone(), k))).style(theme::field).width(260);
    let set = small("Set", (!typed.trim().is_empty()).then(|| wrap(Msg::SetKey(p.id.clone()))));
    let remove = (p.source == "secret").then(|| button(text("Remove").size(13).color(theme::BAD)).style(theme::link).on_press(wrap(Msg::RemoveKey(p.id.clone()))));
    row![name(p), text(key_status(p)).size(13).color(theme::MUTED), field, set].push_maybe(remove).spacing(10).align_y(iced::Center).into()
}

fn codex_row<'a>(state: &State, p: &ProviderView) -> Element<'a, Message> {
    let signed_in = p.source == "signed_in";
    let status = if signed_in { "signed in with ChatGPT" } else { "uses a ChatGPT plan, no key" };
    let action = if signed_in {
        button(text("Sign out").size(13).color(theme::BAD)).style(theme::link).on_press(wrap(Msg::SignOut))
    } else {
        button(text("Sign in with ChatGPT").size(13)).padding([4, 12]).style(theme::secondary).on_press(wrap(Msg::SignIn))
    };
    let line = row![name(p), text(status).size(13).color(theme::MUTED), action].spacing(10).align_y(iced::Center);
    let Some(s) = &state.signing_in else { return line.into() };
    let open = button(text(s.verification_uri.clone()).size(13).color(theme::LINK)).padding(0).style(theme::link).on_press(Message::OpenUrl(s.verification_uri.clone()));
    let waiting = row![text("Open ").size(13), open, text(format!(" and enter {}. Waiting for approval...", s.user_code)).size(13)];
    column![line, waiting].spacing(4).into()
}

fn providers(state: &State) -> Element<'_, Message> {
    let rows = state.providers.iter().map(|p| if p.id == "openai-codex" { codex_row(state, p) } else { key_row(state, p) });
    card("Model providers", Column::with_children(rows).spacing(8).push(text(&state.note).size(13).color(theme::BAD)))
}

fn hosts(state: &State) -> Element<'_, Message> {
    let lede = "Each host serves its models as a provider of its own. A host that needs a key gets it under Model providers.";
    let rows = state.hosts.iter().map(|h| {
        let remove = button(text("Remove").size(13).color(theme::BAD)).style(theme::link).on_press(wrap(Msg::RemoveHost(h.id.clone())));
        row![text(h.name.clone()).font(theme::BOLD), text(format!("{} · {}", h.id, h.api_url)).size(13).color(theme::MUTED), remove].spacing(10).align_y(iced::Center).into()
    });
    let h = &state.new_host;
    let field = |hint: &'static str, value: &str, f: HostField| text_input(hint, value).on_input(move |v| wrap(Msg::HostField(f, v))).style(theme::field);
    let form = row![
        field("Id, such as ollama", &h.id, HostField::Id).width(180),
        field("Name", &h.name, HostField::Name).width(180),
        field("URL, such as http://localhost:11434/v1/chat/completions", &h.api_url, HostField::Url).width(Fill),
        small("Add", Some(wrap(Msg::AddHost))),
    ]
    .spacing(8);
    card("OpenAI-compatible hosts", column![text(lede).size(13).color(theme::MUTED), Column::with_children(rows).spacing(4), form])
}

pub fn view(state: &State) -> [Element<'_, Message>; 2] {
    [providers(state), hosts(state)]
}

#[cfg(test)]
mod tests {
    use super::*;

    fn host(id: &str, url: &str) -> HostView {
        HostView { id: id.into(), name: id.into(), api_url: url.into() }
    }

    #[test]
    fn adding_a_host_with_a_listed_id_replaces_it() {
        let hosts = with_host(vec![host("a", "http://1"), host("b", "http://2")], host("a", "http://3"));
        assert_eq!(hosts.iter().map(|h| h.api_url.as_str()).collect::<Vec<_>>(), ["http://2", "http://3"]);
    }

    #[test]
    fn a_provider_says_where_its_key_comes_from() {
        let p = |source: &str, ready: bool| ProviderView { id: "x".into(), name: "X".into(), source: source.into(), ready };
        assert_eq!(key_status(&p("secret", true)), "key set here");
        assert_eq!(key_status(&p("none", true)), "no key needed");
        assert_eq!(key_status(&p("none", false)), "no key");
    }
}

//! People on a Bastion server and their tokens (D31). Only an admin on a
//! remote server manages them; a token is shown once, when it is issued.

use bastion_protocol::{LOCAL, PersonView, TokenView, command};
use iced::widget::{Column, button, column, pick_list, row, text, text_input};
use iced::{Element, Task};
use serde_json::{Value, json};

use super::{card, small};
use crate::app::Message;
use crate::client::Ask;
use crate::pages::{Ctx, labeled};
use crate::theme;

const ROLES: [&str; 3] = ["admin", "member", "viewer"];

pub struct State {
    me: Option<PersonView>,
    people: Vec<PersonView>,
    tokens: Vec<TokenView>,
    name: String,
    role: String,
    issued: String,
    note: String,
}

impl Default for State {
    fn default() -> Self {
        State { me: None, people: vec![], tokens: vec![], name: String::new(), role: "member".into(), issued: String::new(), note: String::new() }
    }
}

#[derive(Clone, Debug)]
pub enum Msg {
    Me(Result<PersonView, String>),
    People(Result<Vec<PersonView>, String>),
    Tokens(Result<Vec<TokenView>, String>),
    Name(String),
    Role(String),
    Add,
    ChangeRole(String, String),
    Issue(String),
    Issued(String, Result<String, String>),
    Revoke(String),
    Done(Result<Value, String>),
}

fn wrap(msg: Msg) -> Message {
    Message::Settings(super::Msg::People(msg))
}

fn task<T>(ctx: &Ctx, ask: Ask, then: fn(Result<T, String>) -> Msg) -> Task<Message>
where
    T: serde::de::DeserializeOwned + Send + 'static,
{
    ctx.task(&ctx.current, ask, then).map(wrap)
}

/// Whether `me` manages people here: an admin, on a remote Bastion server.
/// `local` listens only on this machine, so nobody else can sign in to it.
fn manages(server: &str, me: Option<&PersonView>) -> bool {
    server != LOCAL && me.is_some_and(|p| p.role == "admin")
}

pub fn load(ctx: &Ctx) -> Task<Message> {
    task(ctx, Ask::bare(command::ME), Msg::Me)
}

fn on_me(state: &mut State, ctx: &Ctx, me: PersonView) -> Task<Message> {
    let manager = manages(&ctx.current, Some(&me));
    state.me = Some(me);
    if !manager {
        return Task::none();
    }
    Task::batch([task(ctx, Ask::bare(command::PEOPLE), Msg::People), task(ctx, Ask::bare(command::TOKENS), Msg::Tokens)])
}

fn issue(ctx: &Ctx, name: String) -> Task<Message> {
    let ask = Ask { cmd: command::TOKEN_ISSUE, args: json!({ "name": name, "label": "issued in Settings" }) };
    let read = ctx.clone().get::<String>(ctx.current.clone(), ask);
    Task::perform(read, move |token| wrap(Msg::Issued(name.clone(), token)))
}

pub fn update(state: &mut State, msg: Msg, ctx: &Ctx) -> Task<Message> {
    match msg {
        Msg::Me(Ok(me)) => return on_me(state, ctx, me),
        Msg::People(Ok(all)) => state.people = all,
        Msg::Tokens(Ok(all)) => state.tokens = all,
        Msg::Me(Err(e)) | Msg::People(Err(e)) | Msg::Tokens(Err(e)) | Msg::Done(Err(e)) => state.note = e,
        Msg::Name(n) => state.name = n,
        Msg::Role(r) => state.role = r,
        Msg::Add => {
            let person = json!({ "person": { "name": state.name.trim(), "role": state.role } });
            state.name.clear();
            return task(ctx, Ask { cmd: command::PERSON_ADD, args: person }, Msg::Done);
        }
        Msg::ChangeRole(name, role) => return task(ctx, Ask { cmd: command::PERSON_ROLE, args: json!({ "name": name, "role": role }) }, Msg::Done),
        Msg::Issue(name) => return issue(ctx, name),
        Msg::Issued(name, Ok(token)) => {
            state.issued = format!("{name}'s new token, shown only now: {token}");
            return load(ctx);
        }
        Msg::Issued(_, Err(e)) => state.note = e,
        Msg::Revoke(id) => return task(ctx, Ask { cmd: command::TOKEN_REVOKE, args: json!({ "id": id }) }, Msg::Done),
        Msg::Done(Ok(_)) => {
            state.note.clear();
            return load(ctx);
        }
    }
    Task::none()
}

fn roles() -> Vec<String> {
    ROLES.iter().map(|r| r.to_string()).collect()
}

fn person_row<'a>(p: &PersonView) -> Element<'a, Message> {
    let name = p.name.clone();
    let role = pick_list(roles(), Some(p.role.clone()), move |r| wrap(Msg::ChangeRole(name.clone(), r))).style(theme::select);
    let token = button(text("Issue a token").size(13).color(theme::LINK)).style(theme::link).on_press(wrap(Msg::Issue(p.name.clone())));
    row![text(p.name.clone()).font(theme::BOLD), role, token].spacing(10).align_y(iced::Center).into()
}

fn token_row<'a>(t: &TokenView) -> Element<'a, Message> {
    let revoke = button(text("Revoke").size(13).color(theme::BAD)).style(theme::link).on_press(wrap(Msg::Revoke(t.id.clone())));
    row![text(t.id.clone()).font(theme::MONO), text(t.person.clone()), text(t.label.clone()).color(theme::MUTED), revoke].spacing(10).align_y(iced::Center).into()
}

pub fn view<'a>(state: &'a State, ctx: &Ctx) -> Element<'a, Message> {
    let who = state.me.as_ref().map(|p| format!("You are {}, a {} on this Bastion server.", p.name, p.role)).unwrap_or_default();
    let mut body = column![text(who).size(13).color(theme::MUTED)];
    if manages(&ctx.current, state.me.as_ref()) {
        let name = text_input("", &state.name).on_input(|n| wrap(Msg::Name(n))).style(theme::field).width(200);
        let role = pick_list(roles(), Some(state.role.clone()), |r| wrap(Msg::Role(r))).style(theme::select);
        body = body
            .push(Column::with_children(state.people.iter().map(person_row)).spacing(6))
            .push(row![labeled("Name", name), labeled("Role", role), small("Add", Some(wrap(Msg::Add)))].spacing(8).align_y(iced::Bottom))
            .push(text(&state.issued).size(13).color(theme::OK))
            .push(text("Tokens").size(13).font(theme::BOLD).color(theme::MUTED))
            .push(Column::with_children(state.tokens.iter().map(token_row)).spacing(6));
    }
    card("People", body.push(text(&state.note).size(13).color(theme::BAD)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_an_admin_on_a_remote_server_manages_people() {
        let admin = PersonView { name: "ana".into(), role: "admin".into() };
        let member = PersonView { role: "member".into(), ..admin.clone() };
        assert!(manages("box", Some(&admin)));
        assert!(!manages(LOCAL, Some(&admin)));
        assert!(!manages("box", Some(&member)));
        assert!(!manages("box", None));
    }
}

//! Where jobs run: the Bastion servers this window knows (D30), the
//! workspaces on the server shown (A3), and the accounts it uses (A7).

use bastion_protocol::{AccountView, LOCAL, Server, Workspace, command};
use iced::widget::{Column, button, column, row, text, text_input};
