    }

    #[test]
    fn dragging_a_step_moves_it_and_stays_on_the_canvas() {
        let mut w = flow();
        let inside_plan = Point::new(PAD + 10.0, PAD + 10.0);
        let (pick, drag) = press(&w, inside_plan, true);
        assert_eq!(pick, Pick::Step("plan".into()));
