        let mid = Point::new(PAD + W + 26.0, PAD + H / 2.0);
        assert_eq!(hit(&w, mid, true), Hit::Link("plan".into(), "skill".into()));
        assert_eq!(hit(&w, Point::new(PAD + W, PAD + H / 2.0), false), Hit::Step("plan".into()));
    }
}

