//! A turn's life in the factory: its session names its job and its step, it
//! ends on its event or its cap, and it ends once. A turn's result reaches
//! the core only while the job still runs that turn, checked in the same
//! save that applies it, so a turn that ended twice, or a stale session
//! found after a restart, changes nothing.

use std::sync::Arc;
use std::time::Duration;

use bastion_core::{Event, Outcome, Stage, State};
use serde_json::json;

use super::{Factory, NS, outcome, short_id, usable};
use crate::evals;
use crate::store::{Record, name};

/// A new turn's session: `<job>-<step>-<random>`.
pub fn session_for(job: &str, stage: Stage) -> String {
    format!("{job}-{}-{}", name(stage), short_id())
}

/// Whether `session` is the turn `record` runs now: its session, at its
/// step, while it runs. A session from before steps were named in it is
/// taken at any step.
pub fn owns(record: &Record, session: &str) -> bool {
    let current = record.runtime.session.as_deref() == Some(session);
    let job = &record.job;
    let step = session.strip_prefix(&format!("{}-", job.id)).and_then(|rest| rest.rsplit_once('-')).map(|(step, _)| step);
    let at_step = step.is_none_or(|s| s == name(job.stage));
    current && at_step && job.state == State::Running
}

impl Factory {
    pub(super) fn listen_for_turn(self: &Arc<Self>, job: &str, session: &str) -> Result<(), String> {
        let factory = self.clone();
        let (id, turn) = (job.to_string(), session.to_string());
        let binding = self.engine.bind(
            "harness::turn-completed",
            json!({ "session_id": session }),
            Arc::new(move |_| {
                let (factory, id, turn) = (factory.clone(), id.clone(), turn.clone());
                crate::rt::spawn(async move { factory.turn_done(&id, &turn, false).await });
                json!({})
            }),
        )?;
        self.hold(job, binding);
        Ok(())
    }

    /// End the turn as failed if it is still running after `secs`.
    pub(super) fn arm_cap(self: &Arc<Self>, job: &str, session: &str, secs: u64) {
        let factory = self.clone();
        let (id, turn) = (job.to_string(), session.to_string());
        crate::rt::spawn(async move {
            tokio::time::sleep(Duration::from_secs(secs)).await;
            factory.turn_done(&id, &turn, true).await;
        });
    }

    /// A turn ended, or ran past its cap. Ignored when the job moved on, and
    /// when another call is finishing the same turn.
    pub(super) async fn turn_done(self: &Arc<Self>, id: &str, session: &str, timed_out: bool) {
        if !self.finishing.lock().unwrap().insert(session.to_string()) {
            return;
        }
        self.finish(id, session, timed_out).await;
        self.finishing.lock().unwrap().remove(session);
    }

    async fn finish(self: &Arc<Self>, id: &str, session: &str, timed_out: bool) {
        let Ok(record) = self.store.load(id).await else {
            return;
        };
        if !owns(&record, session) {
            return;
        }
        let Some(result) = self.result(&record, session, timed_out).await else {
            return;
        };
        self.release(id);
        evals::meter(&*self.engine, &*self.store, &record.job, session).await;
        self.tidy_after_turn(&record).await;
        let turn = session.to_string();
        let holds = Arc::new(move |r: &Record| owns(r, &turn));
        let _ = self.apply_when(id, Event::TurnFinished { outcome: result }, holds).await;
    }

    /// What the turn came to, or none while it still runs.
    async fn result(&self, record: &Record, session: &str, timed_out: bool) -> Option<Outcome> {
        if timed_out {
            let minutes = bastion_core::TURN_CAP_SECS / 60;
            return Some(Outcome::Failed { error: format!("the turn ran past {minutes} minutes") });
        }
        let status = match self.engine.call(NS, "harness::status", json!({ "session_id": session })).await {
            Ok(status) => status,
            Err(error) => return Some(Outcome::Failed { error }),
        };
        if status["status"] != "completed" {
            return None;
        }
        if let Some(error) = status["result_error"].as_str() {
            return Some(Outcome::Failed { error: error.into() });
        }
        Some(match self.final_reply(session).await {
            Ok(reply) => usable(record.job.stage, outcome(&reply)),
            Err(error) => Outcome::Failed { error },
        })
    }
}

