        let was = json!([{ "id": "a" }, { "id": "b" }]);
        assert_eq!(
            retired(&json!(["c"]), &was, &[json!({ "id": "a" })]),
            ["b", "c"]
        );
        assert_eq!(
            retired(&json!(["b"]), &json!(null), &[json!({ "id": "b" })]),
            Vec::<String>::new()
        );
    }

