/// The `argv` of each command the factory ran in the VM.
fn vm_commands(rig: &Rig) -> Vec<String> {
    let calls = rig.engine.calls.lock().unwrap();
    calls
        .iter()
        .filter(|c| c.1 == "sandbox::exec")
        .map(|c| {
            let argv: Vec<&str> = c.2["argv"]
                .as_array()
                .unwrap()
                .iter()
                .map(|a| a.as_str().unwrap())
                .collect();
            argv.join(" ")
        })
        .collect()
}

