    fn host(&self, program: &str, args: &[&str], dir: &Path) -> Result<(), String> {
        let out = self.machine.run(program, args, Some(dir))?;
        match out.success {
            true => Ok(()),
            false => Err(format!("{program} {}: {}", args[0], out.text.trim())),
        }
    }
}

