    async fn resume_turn(self: Arc<Self>, record: Record, out: &turn::Turn) {
        if self.listen_for_turn(out).is_err() {
            return;
        }
        self.arm_cap(out, cap_left(&record.job, now()));
        self.read_charter(&record).await;
        self.turn_done(out, false).await;
    }
